"start": 6,\n                        "end": 7\n                      },\n                      {\n                        "symbol": "concatenation",\n                        "children": [\n                          {\n                            "symbol": "repetition",\n                            "children": [\n                              {\n                                "symbol": "element",\n                                "children": [\n                                  {\n                                    "symbol": "ID",\n                                    "children": [\n                                      {\n                                        "text": "c",\n                                        "start": 8,\n                                        "end": 9\n                                      }\n                                    ]\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "r =/ 2*3%d48",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "rulelist",\n        "children": [\n          {\n            "symbol": "rule_",\n            "children": [\n              {\n                "symbol": "ID",\n                "children": [\n                  {\n                    "text": "r",\n                    "start": 0,\n                    "end": 1\n                  }\n                ]\n              },\n              {\n                "text": "=",\n                "start": 2,\n                "end": 3\n              },\n              {\n                "text": "/",\n                "start": 3,\n                "end": 4\n              },\n              {\n                "symbol": "elements",\n                "children": [\n                  {\n                    "symbol": "alternation",\n                    "children": [\n                      {\n                        "symbol": "concatenation",\n                        "children": [\n                          {\n                            "symbol": "repetition",\n                            "children": [\n                              {\n                                "symbol": "repeat_",\n                                "children": [\n                                  {\n                                    "symbol": "INT",\n                                    "children": [\n                                      {\n                                        "text": "2",\n                                        "start": 5,\n                                        "end": 6\n                                      }\n                                    ]\n                                  },\n                                  {\n                                    "text": "*",\n                                    "start": 6,\n                                    "end": 7\n                                  },\n                                  {\n                                    "symbol": "INT",\n                                    "children": [\n                                      {\n                                        "text": "3",\n                                        "start": 7,\n                                        "end": 8\n                                      }\n                                    ]\n                                  }\n                                ]\n                              },\n                              {\n                                "symbol": "element",\n                                "children": [\n                                  {\n                                    "symbol": "NumberValue",\n                                    "children": [\n                                      {\n                                        "text": "%d48",\n                                        "start": 8,\n                                        "end": 12\n                                      }\n                                    ]\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "a = b ; note\\nc = d",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "rulelist",\n        "children": [\n          {\n            "symbol": "rule_",\n            "children": [\n              {\n                "symbol": "ID",\n                "children": [\n                  {\n                    "text": "a",\n                    "start": 0,\n                    "end": 1\n                  }\n                ]\n              },\n              {\n                "text": "=",\n                "start": 2,\n                "end": 3\n              },\n              {\n                "symbol": "elements",\n                "children": [\n                  {\n                    "symbol": "alternation",\n                    "children": [\n                      {\n                        "symbol": "concatenation",\n                        "children": [\n                          {\n                            "symbol": "repetition",\n                            "children": [\n                              {\n                                "symbol": "element",\n                                "children": [\n                                  {\n                                    "symbol": "ID",\n                                    "children": [\n                                      {\n                                        "text": "b",\n                                        "start": 4,\n                                        "end": 5\n                                      }\n                                    ]\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          },\n          {\n            "symbol": "rule_",\n            "children": [\n              {\n                "symbol": "ID",\n                "children": [\n                  {\n                    "text": "c",\n                    "start": 13,\n                    "end": 14\n                  }\n                ]\n              },\n              {\n                "text": "=",\n                "start": 15,\n                "end": 16\n              },\n              {\n                "symbol": "elements",\n                "children": [\n                  {\n                    "symbol": "alternation",\n                    "children": [\n                      {\n                        "symbol": "concatenation",\n                        "children": [\n                          {\n                            "symbol": "repetition",\n                            "children": [\n                              {\n                                "symbol": "element",\n                                "children": [\n                                  {\n                                    "symbol": "ID",\n                                    "children": [\n                                      {\n                                        "text": "d",\n                                        "start": 17,\n                                        "end": 18\n                        