    'grammar.ug': '# ABNF (RFC 5234, with RFC 7405 case-sensitive strings).\n# Ported from grammars-v4 abnf/Abnf.g4 (commit 7df52be9).\n# Copyright (c) 2013 Rainer Schuster. BSD 3-Clause licence (see NOTICE.md).\n#\n# ABNF has no rule terminator: a rule ends where the next \'ID =\' begins,\n# which the Earley parser resolves without lookahead. COMMENT and WS are on\n# ANTLR\'s hidden channel; here COMMENT is skipped and WS is the whitespace.\n\nstart rulelist;\nwhitespace [ \\t\\r\\n]+;\nskip COMMENT;\n\nrulelist --> rule_* ;\n\nrule_ --> ID \'=\' \'/\'? elements ;\n\nelements --> alternation ;\n\nalternation --> concatenation (\'/\' concatenation)* ;\n\nconcatenation --> repetition+ ;\n\nrepetition --> repeat_? element ;\n\nrepeat_ --> INT | INT? \'*\' INT? ;\n\nelement --> ID | group | option | STRING | NumberValue | ProseValue ;\n\ngroup --> \'(\' alternation \')\' ;\n\noption --> \'[\' alternation \']\' ;\n\n# \'%\' (BinaryValue | DecimalValue | HexValue)\nNumberValue --> \'%\' (?:b[01]+(?:(?:[.][01]+)+|-[01]+)?|d[0-9]+(?:(?:[.][0-9]+)+|-[0-9]+)?|x[0-9a-fA-F]+(?:(?:[.][0-9a-fA-F]+)+|-[0-9a-fA-F]+)?) ;\n\nProseValue --> \'<\' [^>]* \'>\' ;\n\nID --> [a-zA-Z] [a-zA-Z0-9_-]* ;\n\nINT --> [0-9]+ ;\n\nCOMMENT --> \';\' [^\\n\\r]* [\\r]? [\\n] ;\n\nSTRING --> (?:%s|%i)? \'"\' [^"]* \'"\' ;\n',
    'inputs.txt':
