  'port-arithmetic': {
    'case.json': '{\n  "rules": ["S-G1", "S-G3", "S-G4", "S-L2", "S-P2", "S-P4", "S-P8"],\n  "description": "Port of grammars-v4 arithmetic: precedence levels give left-associative + - and ^ (as ANTLR\'s left-recursive rule does), * / binding tighter than + -, ^ tighter than * /, and prefix signs binding to the atom. Maximal munch keeps \'1.5e-3\' one number."\n}\n',
    'expected.json': '{\n  "grammar": {"ok": true},\n  "inputs": [\n    {\n      "input": "a=1-2-3",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "file_", "children": [\n        {"symbol": "equation", "children": [\n          {"symbol": "expression", "children": [\n            {"symbol": "multiplying", "children": [\n              {"symbol": "powering", "children": [\n                {"symbol": "primary", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "variable", "children": [\n                      {"symbol": "VARIABLE", "children": [{"text": "a", "start": 0, "end": 1}]}]}]}]}]}]}]},\n          {"symbol": "relop", "children": [{"text": "=", "start": 1, "end": 2}]},\n          {"symbol": "expression", "children": [\n            {"symbol": "expression", "children": [\n              {"symbol": "expression", "children": [\n                {"symbol": "multiplying", "children": [\n                  {"symbol": "powering", "children": [\n                    {"symbol": "primary", "children": [\n                      {"symbol": "atom", "children": [\n                        {"symbol": "scientific", "children": [\n                          {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "1", "start": 2, "end": 3}]}]}]}]}]}]}]},\n              {"text": "-", "start": 3, "end": 4},\n              {"symbol": "multiplying", "children": [\n                {"symbol": "powering", "children": [\n                  {"symbol": "primary", "children": [\n                    {"symbol": "atom", "children": [\n                      {"symbol": "scientific", "children": [\n                        {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "2", "start": 4, "end": 5}]}]}]}]}]}]}]},\n            {"text": "-", "start": 5, "end": 6},\n            {"symbol": "multiplying", "children": [\n              {"symbol": "powering", "children": [\n                {"symbol": "primary", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "scientific", "children": [\n                      {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "3", "start": 6, "end": 7}]}]}]}]}]}]}]}]}]}\n    },\n    {\n      "input": "a=1.5e-3+2*3",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "file_", "children": [\n        {"symbol": "equation", "children": [\n          {"symbol": "expression"},\n          {"symbol": "relop", "children": [{"text": "="}]},\n          {"symbol": "expression", "children": [\n            {"symbol": "expression", "children": [\n              {"symbol": "multiplying", "children": [\n                {"symbol": "powering", "children": [\n                  {"symbol": "primary", "children": [\n                    {"symbol": "atom", "children": [\n                      {"symbol": "scientific", "children": [\n                        {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "1.5e-3", "start": 2, "end": 8}]}]}]}]}]}]}]},\n            {"text": "+"},\n            {"symbol": "multiplying", "children": [\n              {"symbol": "multiplying", "children": [\n                {"symbol": "powering", "children": [\n                  {"symbol": "primary", "children": [\n                    {"symbol": "atom", "children": [\n                      {"symbol": "scientific", "children": [\n                        {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "2"}]}]}]}]}]}]},\n              {"text": "*"},\n              {"symbol": "powering", "children": [\n                {"symbol": "primary", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "scientific", "children": [\n                      {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "3"}]}]}]}]}]}]}]}]}]}\n    },\n    {\n      "input": "a=2^3^4",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "file_", "children": [\n        {"symbol": "equation", "children": [\n          {"symbol": "expression"},\n          {"symbol": "relop"},\n          {"symbol": "expression", "children": [\n            {"symbol": "multiplying", "children": [\n              {"symbol": "powering", "children": [\n                {"symbol": "powering", "children": [\n                  {"symbol": "powering", "children": [\n                    {"symbol": "primary", "children": [\n                      {"symbol": "atom", "children": [\n                        {"symbol": "scientific", "children": [\n                          {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "2"}]}]}]}]}]},\n                  {"text": "^"},\n                  {"symbol": "primary", "children": [\n                    {"symbol": "atom", "children": [\n                      {"symbol": "scientific", "children": [\n                        {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "3"}]}]}]}]}]},\n                {"text": "^"},\n                {"symbol": "primary", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "scientific", "children": [\n                      {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "4"}]}]}]}]}]}]}]}]}]}\n    },\n    {\n      "input": "a=-2^2",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "file_", "children": [\n        {"symbol": "equation", "children": [\n          {"symbol": "expression"},\n          {"symbol": "relop"},\n          {"symbol": "expression", "children": [\n            {"symbol": "multiplying", "children": [\n              {"symbol": "powering", "children": [\n                {"symbol": "powering", "children": [\n                  {"symbol": "primary", "children": [\n                    {"text": "-"},\n                    {"symbol": "atom", "children": [\n                      {"symbol": "scientific", "children": [\n                        {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "2"}]}]}]}]}]},\n                {"text": "^"},\n                {"symbol": "primary", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "scientific", "children": [\n                      {"symbol": "SCIENTIFIC_NUMBER", "children": [{"text": "2"}]}]}]}]}]}]}]}]}]}\n    },\n    {"input": "a=(1+2", "outcome": "rejected"}\n  ]\n}\n',
    'grammar.ug': '# Equations over arithmetic expressions with scientific numbers.\n# Ported from grammars-v4 arithmetic/arithmetic.g4 (commit 7df52be9).\n# Copyright (c) 2013, Tom Everett. BSD licence (see NOTICE.md).\n#\n# The ANTLR rule \'expression\' is a single left-recursive rule whose\n# alternatives are ordered by precedence (^ over * / over + -), all left\n# associative (ANTLR\'s default). Earley does not use alternative order, so the\n# rule is split into one left-recursive level per precedence:\n# expression (+ -), multiplying (* /), powering (^), primary.\n\nstart file_;\nwhitespace [ \\r\\n\\t]+;\n\nfile_ --> equation* ;\n\nequation --> expression relop expression ;\n\nexpression --> expression (\'+\' | \'-\') multiplying | multiplying ;\n\nmultiplying --> multiplying (\'*\' | \'/\') powering | powering ;\n\npowering --> powering \'^\' primary | primary ;\n\nprimary --> \'(\' expression \')\' | (\'+\' | \'-\')* atom ;\n\natom --> scientific | variable ;\n\nscientific --> SCIENTIFIC_NUMBER ;\n\nvariable --> VARIABLE ;\n\nrelop --> \'=\' | \'>\' | \'<\' ;\n\nVARIABLE --> [a-zA-Z_][a-zA-Z_0-9]* ;\n\nSCIENTIFIC_NUMBER --> [0-9]+ (?:[.][0-9]+)? (?:[Ee][+\\-]?[0-9]+)? ;\n',
    'inputs.txt': 'a=1-2-3\na=1.5e-3+2*3\na=2^3^4\na=-2^2\na=(1+2\n',
