  'port-bnf': {
    'case.json': '{\n  "rules": ["S-G1", "S-G4", "S-L2", "S-P1", "S-P8"],\n  "description": "Port of grammars-v4 BNF: quoted and angle-bracketed elements as single tokens, maximal munch of \'::=\' and \'-->\' over single-character TEXT, production boundaries found without significant newlines, empty right-hand sides, and the two-character minimum for ID."\n}\n',
    'expected.json': '{\n  "grammar": {\n    "ok": true\n  },\n  "inputs": [\n    {\n      "input": "ab ::= \\"x y\\" | <c d>",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "start_",\n        "children": [\n          {\n            "symbol": "prods",\n            "children": [\n              {\n                "symbol": "prod",\n                "children": [\n                  {\n                    "symbol": "xlhs",\n                    "children": [\n                      {\n                        "symbol": "ID",\n                        "children": [\n                          {\n                            "text": "ab",\n                            "start": 0,\n                            "end": 2\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "assign",\n                    "children": [\n                      {\n                        "symbol": "ASSIGN1",\n                        "children": [\n                          {\n                            "text": "::=",\n                            "start": 3,\n                            "end": 6\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "xrhs",\n                    "children": [\n                      {\n                        "symbol": "xalt",\n                        "children": [\n                          {\n                            "symbol": "xelem",\n                            "children": [\n                              {\n                                "symbol": "DQUOTED",\n                                "children": [\n                                  {\n                                    "text": "\\"x y\\"",\n                                    "start": 7,\n                                    "end": 12\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      },\n                      {\n                        "symbol": "or",\n                        "children": [\n                          {\n                            "symbol": "OR1",\n                            "children": [\n                              {\n                                "text": "|",\n                                "start": 13,\n                                "end": 14\n                              }\n                            ]\n                          }\n                        ]\n                      },\n                      {\n                        "symbol": "xalt",\n                        "children": [\n                          {\n                            "symbol": "xelem",\n                            "children": [\n                              {\n                                "symbol": "NAME",\n                                "children": [\n                                  {\n                                    "text": "<c d>",\n                                    "start": 15,\n                                    "end": 20\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "<a> ::= b\\n<c> --> d e",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "start_",\n        "children": [\n          {\n            "symbol": "prods",\n            "children": [\n              {\n                "symbol": "prod",\n                "children": [\n                  {\n                    "symbol": "xlhs",\n                    "children": [\n                      {\n                        "symbol": "NAME",\n                        "children": [\n                          {\n                            "text": "<a>",\n                            "start": 0,\n                            "end": 3\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "assign",\n                    "children": [\n                      {\n                        "symbol": "ASSIGN1",\n                        "children": [\n                          {\n                            "text": "::=",\n                            "start": 4,\n                            "end": 7\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "xrhs",\n                    "children": [\n                      {\n                        "symbol": "xalt",\n                        "children": [\n                          {\n                            "symbol": "xelem",\n                            "children": [\n                              {\n                                "symbol": "TEXT",\n                                "children": [\n                                  {\n                                    "text": "b",\n                                    "start": 8,\n                                    "end": 9\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "prod",\n                "children": [\n                  {\n                    "symbol": "xlhs",\n                    "children": [\n                      {\n                        "symbol": "NAME",\n                        "children": [\n                          {\n                            "text": "<c>",\n                            "start": 10,\n                            "end": 13\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "assign",\n                    "children": [\n                      {\n                        "symbol": "ASSIGN3",\n                        "children": [\n                          {\n                            "text": "-->",\n                            "start": 14,\n                            "end": 17\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "xrhs",\n                    "children": [\n                      {\n                        "symbol": "xalt",\n                        "children": [\n                          {\n                            "symbol": "xelem",\n                            "children": [\n                              {\n                                "symbol": "TEXT",\n                                "children": [\n                                  {\n                                    "text": "d",\n                                    "start": 18,\n                                    "end": 19\n                                  }\n                                ]\n                              }\n                            ]\n                          },\n                          {\n                            "symbol": "xelem",\n                            "children": [\n                              {\n                                "symbol": "TEXT",\n                                "children": [\n                                  {\n                                    "text": "e",\n                                    "start": 20,\n                                    "end": 21\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "xy ::=",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "start_",\n        "children": [\n          {\n            "symbol": "prods",\n            "children": [\n              {\n                "symbol": "prod",\n                "children": [\n                  {\n                    "symbol": "xlhs",\n                    "children": [\n                      {\n                        "symbol": "ID",\n                        "children": [\n                          {\n                            "text": "xy",\n                            "start": 0,\n                            "end": 2\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "assign",\n                    "children": [\n                      {\n                        "symbol": "ASSIGN1",\n                        "children": [\n                          {\n                            "text": "::=",\n                            "start": 3,\n                            "end": 6\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "xrhs",\n                    "children": []\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "x ::= a",\n      "outcome": "rejected"\n    },\n    {\n      "input": "ab ::= c |",\n      "outcome": "rejected"\n    }\n  ]\n}',
    'grammar.ug': '# "Switching" BNF: several BNF metasyntax styles (not EBNF).\n# Ported from grammars-v4 bnf/bnfLexer.g4 and bnf/bnfParser.g4 (commit 7df52be9).\n# Author: Ken Domino (October 2023). MIT License (see NOTICE.md).\n#\n# The ANTLR grammar keeps whitespace and newlines as tokens, but allows them\n# before every element and every \'|\', so productions may continue over\n# several lines. Here whitespace is discarded, quoted and angle-bracketed\n# elements (non-greedy \'.*?\' in the ANTLR parser) are single tokens, and a\n# production ends where the next \'lhs assign\' begins (see NOTICE.md).\n#\n# ANTLR alternatives are separate productions, and grouped sequences are\n# written as groups, as in ANTLR.\n\nstart start_;\n\nstart_ --> prods? ;\n\nprods --> prod+ ;\n\nprod --> xlhs assign xrhs ;\n\nxlhs --> ID | NAME ;\n\nxrhs --> xalt? (or xalt)* ;\n\nxalt --> xelem+ ;\n\nxelem --> DQUOTED | SQUOTED | NAME | ID | TEXT ;\n\nassign --> ASSIGN1 | ASSIGN2 | ASSIGN3 | ASSIGN4 ;\n\nor --> OR1 | OR2 | OR3 ;\n\nASSIGN1 --> \'::=\' ;\nASSIGN2 --> \':≡\' ;\nASSIGN3 --> \'-->\' ;\nASSIGN4 --> \'→\' ;\n\nOR1 --> \'|\' ;\nOR2 --> \'o‾r‾\' ;\nOR3 --> \'∣\' ;\n\nID --> [a-zA-Z] [a-zA-Z0-9_-]+ ;\n\n# ANTLR parser elements \'"\' .*? \'"\', \'\\\'\' .*? \'\\\'\' and \'<\' .*? \'>\'.\nDQUOTED --> \'"\' [^"]* \'"\' ;\nSQUOTED --> "\'" [^\']* "\'" ;\nNAME --> \'<\' [^>]* \'>\' ;\n\n# Any other single character; \'|\', U+2223 and U+2192 are always operators.\nTEXT --> [^\\s|∣→] ;\n',
