    'case.json': '{\n  "rules": ["S-G1", "S-G4", "S-L2", "S-L4", "S-P2", "S-P4", "S-P7", "S-P8"],\n  "description": "Port of the grammars-v4 C grammar: keyword literals versus the Identifier lookahead, skipped preprocessor lines and comments, production costs that stand in for the ANTLR symbol table (T * p; is a declaration, g(p); a call, (a) - b a subtraction), and the open/closed statement feature that binds else to the nearest if."\n}\n',
    'expected.json': '{\n  "grammar": {\n    "ok": true\n  },\n  "inputs": [\n    {\n      "input": "int x;",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "compilationUnit",\n        "children": [\n          {\n            "symbol": "translationUnit",\n            "children": [\n              {\n                "symbol": "externalDeclaration",\n                "children": [\n                  {\n                    "symbol": "declaration",\n                    "children": [\n                      {\n                        "symbol": "declarationSpecifiers",\n                        "children": [\n                          {\n                            "symbol": "declarationSpecifier",\n                            "children": [\n                              {\n                                "symbol": "typeSpecifier",\n                                "children": [\n                                  {\n                                    "text": "int",\n                                    "start": 0,\n                                    "end": 3\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      },\n                      {\n                        "symbol": "initDeclaratorList",\n                        "children": [\n                          {\n                            "symbol": "initDeclarator",\n                            "children": [\n                              {\n                                "symbol": "declarator",\n                                "children": [\n                                  {\n                                    "symbol": "directDeclarator",\n                                    "children": [\n                                      {\n                                        "symbol": "Identifier",\n  