                                            ]\n                                          }\n                                        ]\n                                      }\n                                    ]\n                                  }\n                                ]\n                              },\n                              {\n                                "text": "}",\n                                "start": 28,\n                                "end": 29\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "void f(void) { if (a) if (b) x(); else y(); }",\n      "outcome": "accepted",\n      "penalty": 2,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "compilationUnit",\n        "children": [\n          {\n            "symbol": "translationUnit",\n            "children": [\n              {\n                "symbol": "externalDeclaration",\n                "children": [\n                  {\n                    "symbol": "functionDefinition",\n                    "children": [\n                      {\n                        "symbol": "declarationSpecifiers"\n                      },\n                      {\n                        "symbol": "declarator"\n                      },\n                      {\n                        "symbol": "functionBody",\n                        "children": [\n                          {\n                            "symbol": "compoundStatement",\n                            "children": [\n                              {\n                                "text": "{"\n                              },\n                              {\n                                "symbol": "blockItemList",\n                                "children": [\n                                  {\n                                    "symbol": "blockItem",\n                                    "children": [\n                                      {\n                                        "symbol": "statement",\n                                        "children": [\n                                          {\n                                            "symbol": "selectionStatement",\n                                            "children": [\n                                              {\n                                                "text": "if",\n                                                "start": 15,\n                                                "end": 17\n                                              },\n                                              {\n                                                "text": "("\n                                              },\n                                              {\n                                                "symbol": "expression"\n                                              },\n                                              {\n                                                "text": ")"\n                                              },\n                                              {\n                                                "symbol": "statement",\n                                                "children": [\n                                                  {\n                                                    "symbol": "selectionStatement",\n                                                    "children": [\n                                                      {\n                                                        "text": "if",\n                                                        "start": 22,\n                                                        "end": 24\n                                                      },\n                              