                 ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "int y = (a) - b;",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false\n    },\n    {\n      "input": "int x = 1",\n      "outcome": "rejected"\n    },\n    {\n      "input": "#include <stdio.h>\\nint main(void) { return 0; } // done",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false\n    }\n  ]\n}\n',
    'grammar.ug': '# C (C23 with GNU, Clang and Visual C extensions), ported from ANTLR grammars-v4\n# Source: c/CLexer.g4 and c/CParser.g4 at grammars-v4 commit 7df52be9\n# Copyright (c) 2013 Sam Harwell. BSD licence (3-clause), see NOTICE.md.\n#\n# The ANTLR grammar relies on a symbol table (CParserBase) to tell typedef names\n# from other identifiers. This port has no symbol table. It accepts every reading\n# and uses production costs to prefer one (see NOTICE.md, Deviations):\n#   - a block item that parses as both a declaration and an expression statement\n#     is a declaration (expressionStatement costs 1);\n#   - a parenthesised declarator with nothing after it, `T (x)`, costs 2, so\n#     `f(x);` stays a call;\n#   - a declaration whose only type is a typedef name and that declares nothing\n#     (`x;`) costs 2;\n#   - a cast, `sizeof (type)` and other type-name readings inside expressions\n#     cost 1, so `(a) - b` is a subtraction and `sizeof (x)` takes an expression.\n# Feature `t` on specifier lists (none / builtin / name) enforces the C rule that\n# a typedef name is the only type specifier in its list. Feature `open` on\n# statements resolves the dangling else.\n\nstart compilationUnit;\n# Whitespace and Newline, plus the form feed and vertical tab that C (C11 6.4) also treats as whitespace.\nwhitespace [ \\t\\r\\n\\u000B\\u000C]+;\nskip BlockComment, LineComment, Directive;\n\ncompilationUnit --> translationUnit? ;\n\n# ---------------------------------------------------------------- expressions\n\nconstant --> IntegerConstant | FloatingConstant | CharacterConstant | predefinedConstant ;\n\nenumerationConstant --> Identifier ;\n\npredefinedConstant --> \'false\' | \'true\' | \'nullptr\' ;\n\nprimaryExpression --> Identifier\n                   | constant\n                   | StringLiteral+\n                   | \'(\' expression \')\'\n                   | genericSelection\n                   | \'__func__\'\n                   | \'__FUNCTION__\'\n                   | \'__PRETTY_FUNCTION__\'\n                   | \'__extension__\'? \'(\' compoundStatement \')\'\n                   | \'__builtin_va_arg\' \'(\' unaryExpression \',\' typeName \')\'\n                   | \'__builtin_offsetof\' \'(\' typeName \',\' unaryExpression \')\'\n                   | \'__builtin_choose_expr\' \'(\' unaryExpression \',\' unaryExpression \',\' unaryExpression \')\'\n                   | \'__builtin_types_compatible_p\' \'(\' typeName \',\' typeName \')\'\n                   | \'__builtin_tgmath\' \'(\' exprList \')\'\n                   | \'__builtin_complex\' \'(\' assignmentExpression \',\' assignmentExpression \')\' ;\n\nexprList --> assignmentExpression (\',\' assignmentExpression)* ;\n\ngenericSelection --> \'_Generic\' \'(\' assignmentExpression \',\' genericAssocList \')\' ;\ngenericAssocList --> genericAssociation (\',\' genericAssociation)* ;\ngenericAssociation --> (typeName | \'default\') \':\' assignmentExpression ;\n\npostfixExpression --> (primaryExpression | \'__extension__\'? \'(\' typeName \')\' \'{\' initializerList? \',\'? \'}\')\n                      (\'[\' expression \']\' | \'(\' argumentExpressionList \')\' | (\'.\' | \'->\') Identifier | \'++\' | \'--\')* ;\n\nargumentExpressionList --> assignmentExpression (\',\' assignmentExpression)* | ;\n\nunaryExpression --> postfixExpression\n                 | \'++\' unaryExpression\n                 | \'--\' unaryExpression\n                 | (\'&\' | \'*\' | \'+\' | \'-\' | \'~\' | \'!\' | \'__extension__\' | \'__real__\' | \'__imag__\') castExpression\n                 | \'sizeof\' unaryExpression ;\nunaryExpression --> \'sizeof\' \'(\' typeName \')\' @1 ;\nunaryExpression --> Alignof \'(\' typeName \')\' @1 ;\nunaryExpression --> Countof unaryExpression ;\nunaryExpression --> Countof \'(\' typeName \')\' @1 ;\nunaryExpression --> Alignof unaryExpression\n                 | Maxof \'(\' typeName \')\'\n                 | Minof \'(\' typeName \')\'\n                 | \'&&\' Identifier ;\n\ncastExpression --> \'(\' typeName \')\' castExpression @1 ;\ncastExpression --> unaryExpression | DigitSequence ;\n\nmultiplicativeExpression --> castExpression ((\'*\' | \'/\' | \'%\') castExpression)* ;\nadditiveExpression --> multiplicativeExpression ((\'+\' | \'-\') multiplicativeExpression)* ;\nshiftExpression --> additiveExpression ((\'<<\' | \'>>\') additiveExpression)* ;\nrelationalExpression --> shiftExpression ((\'<\' | \'>\' | \'<=\' | \'>=\') shiftExpression)* ;\nequalityExpression --> relationalExpression ((\'==\' | \'!=\') relationalExpression)* ;\nandExpression --> equalityExpression (\'&\' equalityExpression)* ;\nexclusiveOrExpression --> andExpression (\'^\' andExpression)* ;\ninclusiveOrExpression --> exclusiveOrExpression (\'|\' exclusiveOrExpression)* ;\nlogicalAndExpression --> inclusiveOrExpression (\'&&\' inclusiveOrExpression)* ;\nlogicalOrExpression --> logicalAndExpression (\'||\' logicalAndExpression)* ;\nconditionalExpression --> logicalOrExpression (\'?\' expression \':\' conditionalExpression)? ;\n\nassignmentExpression --> conditionalExpression\n                      | unaryExpression (\'=\' | \'*=\' | \'/=\' | \'%=\' | \'+=\' | \'-=\' | \'<<=\' | \'>>=\' | \'&=\' | \'^=\' | \'|=\') assignmentExpression ;\n\nexpression --> assignmentExpression (\',\' assignmentExpression)* ;\nconstantExpression --> conditionalExpression ;\n\n# --------------------------------------------------------------- declarations\n\ndeclaration --> declarationSpecifiers initDeclaratorList \';\'\n             | declarationSpecifiers{t: none} \';\'\n             | declarationSpecifiers{t: builtin} \';\' ;\ndeclaration --> declarationSpecifiers{t: name} \';\' @2 ;\ndeclaration --> staticAssertDeclaration | attributeDeclaration ;\n\n# At most one typedef name, and never together with another type specifier.\ndeclarationSpecifiers{t: none} --> declarationSpecifier{t: none}+ ;\ndeclarationSpecifiers{t: name} --> declarationSpecifier{t: n