    'grammar.ug': '# Equations over arithmetic expressions with functions and constants.\n# Ported from grammars-v4 calculator/calculator.g4 (commit 7df52be9).\n# Copyright (c) 2013, Tom Everett. BSD licence (see NOTICE.md).\n#\n# ANTLR writes each precedence level as a flat list, e.g.\n#   expression : multiplyingExpression ((PLUS | MINUS) multiplyingExpression)* ;\n# which leaves associativity to the tree walker. The port nests the levels so\n# the tree shows it: + - and * / are left associative, ^ is right associative\n# (the usual mathematical reading of a^b^c). Prefix signs bind tighter than ^,\n# as in ANTLR, where signedAtom is the operand of POW.\n\nstart equation;\nwhitespace [ \\r\\n\\t]+;\n\nequation --> expression relop expression ;\n\nexpression --> expression (\'+\' | \'-\') multiplyingExpression | multiplyingExpression ;\n\nmultiplyingExpression --> multiplyingExpression (\'*\' | \'/\') powExpression | powExpression ;\n\npowExpression --> signedAtom \'^\' powExpression | signedAtom ;\n\nsignedAtom --> \'+\' signedAtom | \'-\' signedAtom | func_ | atom ;\n\natom --> scientific | variable | constant | \'(\' expression \')\' ;\n\nscientific --> SCIENTIFIC_NUMBER ;\n\nconstant --> \'pi\' | \'e\' | \'i\' ;\n\nvariable --> VARIABLE ;\n\n# ANTLR: funcname LPAREN expression (COMMA expression)* RPAREN.\nfunc_ --> funcname \'(\' expression (\',\' expression)* \')\' ;\n\nfuncname --> \'cos\' | \'tan\' | \'sin\' | \'acos\' | \'atan\' | \'asin\' | \'log\' | \'ln\' | \'sqrt\' ;\n\nrelop --> \'=\' | \'>\' | \'<\' ;\n\n# ANTLR declares the keyword tokens before VARIABLE, so on an equal-length\n# match the keyword wins. Here equal-length matches are alternatives, so\n# VARIABLE excludes the exact keywords with a negative lookahead.\nVARIABLE --> (?!(?:cos|sin|tan|acos|asin|atan|ln|log|sqrt|pi|e|i)(?![a-zA-Z_0-9]))[a-zA-Z_][a-zA-Z_0-9]* ;\n\nSCIENTIFIC_NUMBER --> [0-9]+ (?:[.][0-9]+)? (?:[Ee][+\\-]?[0-9]+(?:[.][0-9]+)?)? ;\n',
