    'grammar.ug': '# Port of grammars-v4 csv/CSV.g4 (commit 7df52be9).\n# Copyright (c) 2013 Terence Parr, BSD licence (as stated in the .g4 header).\n#\n# Newlines end rows and spaces belong to fields, so nothing is discarded as whitespace.\n\nstart csvFile;\nwhitespace none;\n\ncsvFile --> hdr row+ ;\n\nhdr --> row ;\n\nrow --> field (\',\' field)* \'\\r\'? \'\\n\' ;\n\nfield --> TEXT | STRING | ;\n\nTEXT --> [^,\\n\\r"]+ ;\n\n# quote-quote is an escaped quote\nSTRING --> \'"\' (?:""|[^"])* \'"\' ;\n',
