    'grammar.ug': '# Graphviz DOT language.\n# Ported from grammars-v4 dot/DOT.g4 (commit 7df52be9).\n# Copyright (c) 2013 Terence Parr, modified by Andrzej Borucki (2025).\n# BSD licence (see NOTICE.md).\n#\n# The ANTLR grammar sets caseInsensitive = true: keywords use explicit\n# upper/lower character classes and ID accepts both cases.\n\nstart graph;\nwhitespace [ \\t\\n\\r]+;\nskip COMMENT, LINE_COMMENT, PREPROC;\n\ngraph --> STRICT? (GRAPH | DIGRAPH) id_? \'{\' stmt_list \'}\' ;\n\nstmt_list --> (stmt \';\'?)* ;\n\nstmt --> node_stmt | edge_stmt | attr_stmt | id_ \'=\' id_ | subgraph ;\n\nattr_stmt --> (GRAPH | NODE | EDGE) attr_list ;\n\nattr_list --> (\'[\' a_list? \']\')+ ;\n\na_list --> (id_ (\'=\' id_)? (\';\' | \',\')?)+ ;\n\nedge_stmt --> (node_id | subgraph) edgeRHS attr_list? ;\n\nedgeRHS --> (edgeop (node_id | subgraph))+ ;\n\nedgeop --> \'->\' | \'--\' ;\n\nnode_stmt --> node_id attr_list? ;\n\nnode_id --> id_ port? ;\n\nport --> \':\' id_ (\':\' id_)? ;\n\nsubgraph --> (SUBGRAPH id_?)? \'{\' stmt_list \'}\' ;\n\nid_ --> ID | STRING | HTML_STRING | NUMBER ;\n\n# Keywords are case-independent.\nSTRICT --> [sS][tT][rR][iI][cC][tT] ;\nGRAPH --> [gG][rR][aA][pP][hH] ;\nDIGRAPH --> [dD][iI][gG][rR][aA][pP][hH] ;\nNODE --> [nN][oO][dD][eE] ;\nEDGE --> [eE][dD][gG][eE] ;\nSUBGRAPH --> [sS][uU][bB][gG][rR][aA][pP][hH] ;\n\n# "a numeral [-]?(.[0-9]+ | [0-9]+(.[0-9]*)? )"\nNUMBER --> [-]? (?:[.][0-9]+|[0-9]+(?:[.][0-9]*)?) ;\n\n# Double-quoted string with backslash escapes.\nSTRING --> \'"\' (?:[^"\\\\]|[\\\\].)* \'"\' ;\n\n# Letters, underscores and digits, not beginning with a digit; never a keyword.\nID --> (?!(?:[sS][tT][rR][iI][cC][tT]|[gG][rR][aA][pP][hH]|[dD][iI][gG][rR][aA][pP][hH]|[nN][oO][dD][eE]|[eE][dD][gG][eE]|[sS][uU][bB][gG][rR][aA][pP][hH])(?![A-Za-z0-9_])) [A-Za-z_][A-Za-z0-9_]* ;\n\n# HTML strings: one level of nested tags inside angle brackets.\nHTML_STRING --> \'<\' (?:<[^>]*>|[^<>])* \'>\' ;\n\nCOMMENT --> \'/*\' (?:[^*]|[*]+[^*/])* [*]+ \'/\' ;\nLINE_COMMENT --> \'//\' [^\\n]* [\\n] ;\nPREPROC --> \'#\' [^\\r\\n]* ;\n',
