stComprehension --> \'[\' expr \'||\' lcExprs \']\' ;\n\nbinaryComprehension --> \'<<\' exprMax \'||\' lcExprs \'>>\' ;\n\nlcExprs --> lcExpr (\',\' lcExpr)* ;\n\nlcExpr --> expr | expr \'<-\' expr | binary \'<=\' expr ;\n\ntuple_ --> \'{\' exprs? \'}\' ;\n\nmapExpr --> exprMax? \'#\' mapTuple | mapExpr \'#\' mapTuple ;\n\nmapTuple --> \'{\' (mapField (\',\' mapField)*)? \'}\' ;\n\nmapField --> mapFieldAssoc | mapFieldExact ;\n\nmapFieldAssoc --> mapKey \'=>\' expr ;\n\nmapFieldExact --> mapKey \':=\' expr ;\n\nmapKey --> expr ;\n\nrecordExpr --> exprMax? \'#\' tokAtom (\'.\' tokAtom | recordTuple) | recordExpr \'#\' tokAtom (\'.\' tokAtom | recordTuple) ;\n\nrecordTuple --> \'{\' recordFields? \'}\' ;\n\nrecordFields --> recordField (\',\' recordField)* ;\n\nrecordField --> (tokVar | tokAtom) \'=\' expr ;\n\nfunctionCall --> expr800 argumentList ;\n\nifExpr --> \'if\' ifClauses \'end\' ;\n\nifClauses --> ifClause (\';\' ifClause)* ;\n\nifClause --> guard_ clauseBody ;\n\ncaseExpr --> \'case\' expr \'of\' crClauses \'end\' ;\n\ncrClauses --> crClause (\';\' crClause)* ;\n\ncrClause --> expr clauseGuard clauseBody ;\n\nreceiveExpr --> \'receive\' crClauses \'end\' | \'receive\' \'after\' expr clauseBody \'end\' | \'receive\' crClauses \'after\' expr clauseBody \'end\' ;\n\nfunExpr --> \'fun\' tokAtom \'/\' tokInteger | \'fun\' atomOrVar \':\' atomOrVar \'/\' integerOrVar | \'fun\' funClauses \'end\' ;\n\natomOrVar --> tokAtom | tokVar ;\n\nintegerOrVar --> tokInteger | tokVar ;\n\nfunClauses --> funClause (\';\' funClause)* ;\n\nfunClause --> patArgumentList clauseGuard clauseBody | tokVar patArgumentList clauseGuard clauseBody ;\n\ntryExpr --> \'try\' exprs (\'of\' crClauses)? tryCatch ;\n\ntryCatch --> \'catch\' tryClauses \'end\' | \'catch\' tryClauses \'after\' exprs \'end\' | \'after\' exprs \'end\' ;\n\ntryClauses --> tryClause (\';\' tryClause)* ;\n\n# Follows erl_parse.yrl rather than the ANTLR rule. The ANTLR alternative\n# \'expr clauseGuard clauseBody\' is