                 {\n                                "text": "\\n",\n                                "start": 28,\n                                "end": 29\n                              }\n                            ]\n                          }\n                        ]\n                      },\n                      {\n                        "symbol": "statement",\n                        "children": [\n                          {\n                            "symbol": "simpleStmt",\n                            "children": [\n                              {\n                                "symbol": "expressionStmt",\n                                "children": [\n                                  {\n                                    "symbol": "expression",\n                                    "children": [\n                                      {\n                                        "symbol": "andExpr",\n                                        "children": [\n                                          {\n                                            "symbol": "relExpr",\n                                            "children": [\n                                              {\n                                                "symbol": "addExpr",\n                                                "children": [\n                                                  {\n                                                    "symbol": "mulExpr",\n                                                    "children": [\n                                                      {\n                                                        "symbol": "unaryExpr",\n                                                        "children": [\n                                                          {\n                                                            "symbol": "STAR",\n                                                            "children": [\n                                           