                   ]\n                          }\n                        ]\n                      }\n                    ]\n                  },\n                  {\n                    "symbol": "R_CURLY",\n                    "children": [\n                      {\n                        "text": "}",\n                        "start": 32,\n                        "end": 33\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          },\n          {\n            "symbol": "eos",\n            "children": []\n          }\n        ]\n      }\n    },\n    {\n      "input": "package p\\nfunc f() { x := 1 y := 2 }",\n      "outcome": "rejected"\n    },\n    {\n      "input": "package p\\nvar a = []int{\\n1,\\n2\\n}",\n      "outcome": "rejected"\n    },\n    {\n      "input": "package p /* c */; import (\\"a\\"; \\"b\\") // end",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "sourceFile",\n        "children": [\n          {\n            "symbol": "packageClause",\n            "children": [\n              {\n                "symbol": "PACKAGE",\n                "children": [\n                  {\n                    "text": "package",\n                    "start": 0,\n                    "end": 7\n                  }\n                ]\n              },\n              {\n                "symbol": "packageName",\n                "children": [\n                  {\n                    "symbol": "identifier",\n                    "children": [\n                      {\n                        "symbol": "IDENTIFIER",\n                        "children": [\n                          {\n                            "text": "p",\n                            "start": 8,\n                            "end": 9\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          },\n          {\n            "symbol": "eos",\n            "children": [\n              {\n                "symbol": "EOS",\n                "children": [\n                  {\n                    "text": ";",\n                    "start": 17,\n                    "end": 18\n                  }\n                ]\n              }\n            ]\n          },\n          {\n            "symbol": "importDecl",\n            "children": [\n              {\n                "symbol": "IMPORT",\n                "children": [\n                  {\n                    "text": "import",\n                    "start": 19,\n                    "end": 25\n                  }\n                ]\n              },\n              {\n                "symbol": "L_PAREN",\n                "children": [\n                  {\n                    "text": "(",\n                    "start": 26,\n                    "end": 27\n                  }\n                ]\n              },\n              {\n                "symbol": "importSpec",\n                "children": [\n                  {\n                    "symbol": "importPath",\n                    "children": [\n                      {\n                        "symbol": "string_",\n                        "children": [\n                          {\n                            "symbol": "INTERPRETED_STRING_LIT",\n                            "children": [\n                              {\n                                "text": "\\"a\\"",\n                                "start": 27,\n                                "end": 30\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "eos",\n                "children": [\n                  {\n                    "symbol": "EOS",\n                    "children": [\n                      {\n                        "text": ";",\n                        "start": 30,\n                        "end": 31\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "importSpec",\n                "children": [\n                  {\n                    "symbol": "importPath",\n                    "children": [\n                      {\n                        "symbol": "string_",\n                        "children": [\n                          {\n                            "symbol": "INTERPRETED_STRING_LIT",\n                            "children": [\n                              {\n                                "text": "\\"b\\"",\n                                "start": 32,\n                                "end": 35\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "eos",\n                "children": []\n              },\n              {\n                "symbol": "R_PAREN",\n                "children": [\n                  {\n                    "text": ")",\n                    "start": 35,\n                    "end": 36\n                  }\n                ]\n              }\n            ]\n          },\n          {\n            "symbol": "eos",\n            "children": []\n          }\n        ]\n      }\n    },\n    {\n      "input": "package p\\nfunc f() { return }",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false\n    }\n  ]\n}\n',
    'grammar.ug': '# Go, ported from grammars-v4 golang/GoLexer.g4 and golang/GoParser.g4\n# (commit 7df52be9). BSD licence. Copyright (c) 2017 Sasa Coh, Michal Blotniak;\n# (c) 2019 Ivan Kochurkin, Positive Technologies; (c) 2019 Dmitry Rassadin,\n# Positive Technologies; (c) 2021 Martin Mirchev; (c) 2023 Dmitry Litovchenko.\n# See NOTICE.md for the list of deviations from the ANTLR grammar.\n#\n# Automatic semicolon insertion follows the ANTLR lexer. The tokens that end a\n# Go statement switch to the lexical state NLSEMI (ANTLR mode(NLSEMI)), every\n# other token switches back to DEFAULT, and in NLSEMI a line break, \';\' or a\n# multi-line comment is an EOS token. Every token is therefore a named category\n# with its mode change: an inline literal could not carry one.\n\nstart sourceFile;\nwhitespace none;\nskip WS, COMMENT, LINE_COMMENT, WS_NLSEMI, COMMENT_NLSEMI, LINE_COMMENT_NLSEMI;\n\n# ---------------------------------------------------------------- tokens\n\n# Whitespace and comments, by mode. In NLSEMI only blanks and single-line comments are skipped.\nWS --> {DEFAULT} [ \\t\\r\\n]+ ;\nCOMMENT --> {DEFAULT} \'/*\' (?:[^*]|[*]+[^*/])* [*]+ \'/\' ;\nLINE_COMMENT --> {DEFAULT} \'//\' [^\\r\\n]* ;\nWS_NLSEMI --> {NLSEMI} [ \\t]+ ;\nCOMMENT_NLSEMI --> {NLSEMI} \'/*\' (?:[^*\\r\\n]|[*]+[^*/\\r\\n])* [*]+ \'/\' ;\nLINE_COMMENT_NLSEMI --> {NLSEMI} \'//\' [^\\r\\n]* ;\n\n# A line break, \';\' or a multi-line comment after a statement-ending token.\nEOS --> {NLSEMI} (?:[\\r\\n]+|;|/\\*(?:[^*]|[*]+[^*/])*[*]+/) ==> ^DEFAULT ;\n\nSEMI --> {DEFAULT} \';\' ==> ^DEFAULT ;\n\n# Keywords\nBREAK --> \'break\' ==> ^NLSEMI ;\nCASE --> \'case\' ==> ^DEFAULT ;\nCHAN --> \'chan\' ==> ^DEFAULT ;\nCONST --> \'const\' ==> ^DEFAULT ;\nCONTINUE --> \'continue\' ==> ^NLSEMI ;\nDEFAULT --> \'default\' ==> ^DEFAULT ;\nDEFER --> \'defer\' ==> ^DEFAULT ;\nELSE --> \'else\' ==> ^DEFAULT ;\nFALLTHROUGH --> \'fallthrough\' ==> ^NLSEMI ;\nFOR --> \'for\' ==> ^DEFAULT ;\nFUNC --> \'func\' ==> ^DEFAULT ;\nGO --> \'go\' ==> ^DEFAULT ;\nGOTO --> \'goto\' ==> ^DEFAULT ;\nIF --> \'if\' ==> ^DEFAULT ;\nIMPORT --> \'import\' ==> ^DEFAULT ;\nINTERFACE --> \'interface\' ==> ^DEFAULT ;\nMAP --> \'map\' ==> ^DEFAULT ;\nNIL_LIT --> \'nil\' ==> ^NLSEMI ;\nPACKAGE --> \'package\' ==> ^DEFAULT ;\nRANGE --> \'range\' ==> ^DEFAULT ;\nRETURN --> \'return\' ==> ^NLSEMI ;\nSELECT --> \'select\' ==> ^DEFAULT ;\nSTRUCT --> \'struct\' ==> ^DEFAULT ;\nSWITCH --> \'switch\' ==> ^DEFAULT ;\nTYPE --> \'type\' ==> ^DEFAULT ;\nVAR --> \'var\' ==> ^DEFAULT ;\n\n# Every keyword and nil are excluded, so they never tie with IDENTIFIER (S-L2).\nIDENTIFIER --> (?!(?:break|case|chan|const|continue|default|defer|else|fallthrough|for|func|goto|go|if|import|interface|map|nil|package|range|return|select|struct|switch|type|var)(?![\\p{L}\\p{Nd}_])) [\\p{L}_] [\\p{L}\\p{Nd}_]* ==> ^NLSEMI ;\n\n# Punctuation and operators\nL_PAREN --> \'(\' ==> ^DEFAULT ;\nR_PAREN --> \')\' ==> ^NLSEMI ;\nL_CURLY --> \'{\' ==> ^DEFAULT ;\nR_CURLY --> \'}\' ==> ^NLSEMI ;\nL_BRACKET --> \'[\' ==> ^DEFAULT ;\nR_BRACKET --> \']\' ==> ^NLSEMI ;\nASSIGN --> \'=\' ==> ^DEFAULT ;\nCOMMA --> \',\' ==> ^DEFAULT ;\nCOLON --> \':\' ==> ^DEFAULT ;\nDOT --> \'.\' ==> ^DEFAULT ;\nPLUS_PLUS --> \'++\' ==> ^NLSEMI ;\nMINUS_MINUS --> \'--\' ==> ^NLSEMI ;\nDECLARE_ASSIGN --> \':=\' ==> ^DEFAULT ;\nELLIPSIS --> \'...\' ==> ^DEFAULT ;\nLOGICAL_OR --> \'||\' ==> ^DEFAULT ;\nLOGICAL_AND --> \'&&\' ==> ^DEFAULT ;\nEQUALS --> \'==\' ==> ^DEFAULT ;\nNOT_EQUALS --> \'!=\' ==> ^DEFAULT ;\nLESS --> \'<\' ==> ^DEFAULT ;\nLESS_OR_EQUALS --> \'<=\' ==> ^DEFAULT ;\nGREATER --> \'>\' ==> ^DEFAULT ;\nGREATER_OR_EQUALS --> \'>=\' ==> ^DEFAULT ;\nOR --> \'|\' ==> ^DEFAULT ;\nDIV --> \'/\' ==> ^DEFAULT ;\nMOD --> \'%\' ==> ^DEFAULT ;\nLSHIFT --> \'<<\' ==> ^DEFAULT ;\nRSHIFT --> \'>>\' ==> ^DEFAULT ;\nBIT_CLEAR --> \'&^\' ==> ^DEFAULT ;\nUNDERLYING --> \'~\' ==> ^DEFAULT ;\nEXCLAMATION --> \'!\' ==> ^DEFAULT ;\nPLUS --> \'+\' ==> ^DEFAULT ;\nMINUS --> \'-\' ==> ^DEFAULT ;\nCARET --> \'^\' ==> ^DEFAULT ;\nSTAR --> \'*\' ==> ^DEFAULT ;\nAMPERSAND --> \'&\' ==> ^DEFAULT ;\nRECEIVE --> \'<-\' ==> ^DEFAULT ;\n\n# Literals\nDECIMAL_LIT --> (?:0|[1-9](?:_?[0-9])*) ==> ^NLSEMI ;\nBINARY_LIT --> \'0\' [bB] (?:_?[01])+ ==> ^NLSEMI ;\nOCTAL_LIT --> \'0\' [oO]? (?:_?[0-7])+ ==> ^NLSEMI ;\nHEX_LIT --> \'0\' [xX] (?:_?[0-9a-fA-F])+ ==> ^NLSEMI ;\n\nFLOAT_LIT --> [0-9] (?:_?[0-9])* (?:[.](?:[0-9](?:_?[0-9])*)?(?:[eE][+-]?[0-9](?:_?[0-9])*)?|[eE][+-]?[0-9](?:_?[0-9])*) ==> ^NLSEMI ;\nFLOAT_LIT --> [.] [0-9] (?:_?[0-9])* (?:[eE][+-]?[0-9](?:_?[0-9])*)? ==> ^NLSEMI ;\nFLOAT_LIT --> \'0\' [xX] (?:(?:_?[0-9a-fA-F])+(?:[.](?:_?[0-9a-fA-F])*)?|[.][0-9a-fA-F](?:_?[0-9a-fA-F])*) [pP] [+-]? [0-9] (?:_?[0-9])* ==> ^NLSEMI ;\nIMAGINARY_LIT --> (?:0[xX](?:(?:_?[0-9a-fA-F])+(?:[.](?:_?[0-9a-fA-F])*)?|[.][0-9a-fA-F](?:_?[0-9a-fA-F])*)[pP][+-]?[0-9](?:_?[0-9])*|[0-9](?:_?[0-9])*(?:[.](?:[0-9](?:_?[0-9])*)?(?:[eE][+-]?[0-9](?:_?[0-9])*)?|[eE][+-]?[0-9](?:_?[0-9])*)|[.][0-9](?:_?[0-9])*(?:[eE][+-]?[0-9](?:_?[0-9])*)?|0[xX](?:_?[0-9a-fA-F])+|0[bB](?:_?[01])+|0[oO]?(?:_?[0-7])+|0|[1-9](?:_?[0-9])*) \'i\' ==> ^NLSEMI ;\nRUNE_LIT --> [\'] (?:[\\\\]u[0-9a-fA-F]{4}|[\\\\]U[0-9a-fA-F]{8}|[\\\\][abfnrtv\\\\\'"]|[\\\\][0-7]{3}|[\\\\]x[0-9a-fA-F]{2}|[^\\r\\n\']) [\'] ==> ^NLSEMI ;\nRAW_STRING_LIT --> [`] [^`]* [`] ==> ^NLSEMI ;\nINTERPRETED_STRING_LIT --> ["] (?:[^"\\\\]|[\\\\](?:u[0-9a-fA-F]{4}|U[0-9a-fA-F]{8}|[abfnrtv\\\\\'"]|[0-7]{3}|x[0-9a-fA-F]{2}))* ["] ==> ^NLSEMI ;\n\n# ---------------------------------------------------------------- source files\n\nsourceFile --> packageClause eos (importDecl eos)* ((functionDecl | methodDecl | declaration) eos)* ;\n\npackageClause --> PACKAGE packageName ;\n\npackageName --> identifier ;\n\nidentifier --> IDENTIFIER ;\n\nimportDecl --> IMPORT (importSpec | L_PAREN (importSpec eos)* R_PAREN) ;\n\nimportSpec --> (DOT | packageName)? importPath ;\n\nimportPath --> string_ ;\n\ndeclaration --> constDecl | typeDecl | varDecl ;\n\nconstDecl --> CONST (constSpec | L_PAREN (constSpec eos)* R_PAREN) ;\n\nconstSpec --> identifierList (type_? ASSIGN expressionList)? ;\n\nidentifierList --> IDENTIFIER (COMMA IDENTIFIER)* ;\n\nexpressionList --> expression (COMMA expression)* ;\n\ntypeDecl --> TYPE (typeSpec | L_PAREN (typeSpec eos)* R_PAREN) ;\n\ntypeSpec --> aliasDecl | typeDef ;\n\naliasDecl --> IDENTIFIER typeParameters? ASSIGN type_ ;\n\ntypeDef --> IDENTIFIER typeParameters? type_ ;\n\ntypeParameters --> L_BRACKET typeParameterDecl (COMMA typeParameterDecl)* COMMA? R_BRACKET ;\n\ntypeParameterDecl --> identifierList typeElement ;\n\ntypeElement --> typeTerm (OR typeTerm)* ;\n\ntypeTerm --> UNDERLYING? type_ ;\n\nfunctionDecl --> FUNC IDENTIFIER typeParameters? signature block? ;\n\nmethodDecl --> FUNC receiver IDENTIFIER signature block? ;\n\nreceiver --> parameters ;\n\nvarDecl --> VAR (varSpec | L_PAREN (varSpec eos)* R_PAREN) ;\n\nvarSpec --> identifierList (type_ (ASSIGN expressionList)? | ASSIGN expressionList) ;\n\n# ---------------------------------------------------------------- statements\n\nblock --> L_CURLY statementList R_CURLY ;\n\nstatementList --> ((SEMI | EOS | ) statement eos)* ;\n\nstatement --> declaration | labeledStmt | simpleStmt | goStmt | returnStmt | breakStmt | continueStmt\n           | gotoStmt | fallthroughStmt | block | ifStmt | switchStmt | selectStmt | forStmt | deferStmt ;\n\nsimpleStmt --> sendStmt | incDecStmt | assignment | expressionStmt | shortVarDecl ;\n\nexpressionStmt --> expression ;\n\nsendStmt --> expression RECEIVE expression ;\n\nincDecStmt --> expression (PLUS_PLUS | MINUS_MINUS) ;\n\nassignment --> expressionList assign_op expressionList ;\n\nassign_op --> (PLUS | MINUS | OR | CARET | STAR | DIV | MOD | LSHIFT | RSHIFT | AMPERSAND | BIT_CLEAR)? ASSIGN ;\n\nshortVarDecl --> identifierList DECLARE_ASSIGN expressionList ;\n\nlabeledStmt --> IDENTIFIER COLON statement? ;\n\nreturnStmt --> RETURN expressionList? ;\n\nbreakStmt --> BREAK IDENTIFIER? ;\n\ncontinueStmt --> CONTINUE IDENTIFIER? ;\n\ngotoStmt --> GOTO IDENTIFIER ;\n\nfallthroughStmt --> FALLTHROUGH ;\n\ndeferStmt --> DEFER expression ;\n\nifStmt --> IF (expression | (SEMI | EOS) expression | simpleStmt (SEMI | EOS) expression) block (ELSE (ifStmt | block))? ;\n\nswitchStmt --> exprSwitchStmt | typeSwitchStmt ;\n\nexprSwitchStmt --> SWITCH (expression? | simpleStmt? eos expression?) L_CURLY exprCaseClause* R_CURLY ;\n\nexprCaseClause --> exprSwitchCase COLON statementList ;\n\nexprSwitchCase --> CASE expressionList | DEFAULT ;\n\ntypeSwitchStmt --> SWITCH (typeSwitchGuard | eos typeSwitchGuard | simpleStmt eos typeSwitchGuard) L_CURLY typeCaseClause* R_CURLY ;\n\ntypeSwitchGuard --> (IDENTIFIER DECLARE_ASSIGN)? primaryExpr DOT L_PAREN TYPE R_PAREN ;\n\ntypeCaseClause --> typeSwitchCase COLON statementList ;\n\ntypeSwitchCase --> CASE typeList | DEFAULT ;\n\ntypeList --> (type_ | NIL_LIT) (COMMA (type_ | NIL_LIT))* ;\n\nselectStmt --> SELECT L_CURLY commClause* R_CURLY ;\n\ncommClause --> commCase COLON statementList ;\n\ncommCase --> CASE (sendStmt | recvStmt) | DEFAULT ;\n\nrecvStmt --> (expressionList ASSIGN | identifierList DECLARE_ASSIGN)? expression ;\n\nforStmt --> FOR (condition | forClause | rangeClause)? block ;\n\ncondition --> expression ;\n\nforClause --> simpleStmt? eos expression? eos simpleStmt? ;\n\nrangeClause --> (expressionList ASSIGN | identifierList DECLARE_ASSIGN)? RANGE expression ;\n\ngoStmt --> GO expression ;\n\n# ANTLR: SEMI | EOS | {closingBracket()}?, which accepts an empty eos when the\n# next token is \')\' or \'}\', or at the end of the input.\neos --> SEMI | EOS ;\neos --> where before(\'R_PAREN\', \'R_CURLY\') | at_end() ;\n\n# ---------------------------------------------------------------- types\n\ntype_ --> typeName typeArgs? | typeLit | L_PAREN type_ R_PAREN ;\n\ntypeArgs --> L_BRACKET typeList COMMA? R_BRACKET ;\n\ntypeName --> qualifiedIdent | IDENTIFIER ;\n\ntypeLit --> arrayType | structType | pointerType | functionType | interfaceType | sliceType | mapType | channelType ;\n\narrayType --> L_BRACKET arrayLength R_BRACKET elementType ;\n\narrayLength --> expression ;\n\nelementType --> type_ ;\n\npointerType --> STAR type_ ;\n\ninterfaceType --> INTERFACE L_CURLY ((methodSpec | typeElement) eos)* R_CURLY ;\n\nsliceType --> L_BRACKET R_BRACKET elementType ;\n\nmapType --> MAP L_BRACKET type_ R_BRACKET elementType ;\n\n# ANTLR: ({isNotReceive()}? CHAN | CHAN RECEIVE | RECEIVE CHAN) elementType. The\n# predicate attaches \'<-\' to the leftmost \'chan\'; here the element type of a\n# bidirectional channel cannot itself be a receive channel.\nchannelType --> CHAN chanElementType | CHAN RECEIVE elementType | RECEIVE CHAN elementType ;\n\n# Not in the ANTLR grammar: type_ without the \'<-\' \'chan\' form.\nchanElementType --> typeName typeArgs?\n                 | L_PAREN type_ R_PAREN\n                 | arrayType | structType | pointerType | functionType | interfaceType | sliceType | mapType\n                 | CHAN chanElementType\n                 | CHAN RECEIVE elementType ;\n\nmethodSpec --> IDENTIFIER parameters result | IDENTIFIER parameters ;\n\nfunctionType --> FUNC signature ;\n\nsignature --> parameters result? ;\n\n# A result starting with \'(\' is always a parameter list (ANTLR chooses this by\n# alternative order), so a parenthesised type is not a result on its own.\nresult --> parameters | typeName typeArgs? | typeLit ;\n\n# Either every parameter is named or none is (the Go specification); the\n# ANTLR rule identifierList? ELLIPSIS? type_ is ambiguous for \'(a, b int)\'.\nparameters --> L_PAREN ((parameterDecl (COMMA parameterDecl)* | parameterType (COMMA parameterType)*) COMMA?)? R_PAREN ;\n\nparameterDecl --> identifierList ELLIPSIS? type_ ;\n\nparameterType --> ELLIPSIS? type_ ;\n\n# ---------------------------------------------------------------- expressions\n\n# Precedence levels replace the ANTLR left-recursive rule with operator\n# alternatives: || < && < comparison < additive < multiplicative < unary.\nexpression --> expression LOGICAL_OR andExpr | andExpr ;\n\nandExpr --> andExpr LOGICAL_AND relExpr | relExpr ;\n\nrelExpr --> relExpr (EQUALS | NOT_EQUALS | LESS | LESS_OR_EQUALS | GREATER | GREATER_OR_EQUALS) addExpr | addExpr ;\n\naddExpr --> addExpr (PLUS | MINUS | OR | CARET) mulExpr | mulExpr ;\n\nmulExpr --> mulExpr (STAR | DIV | MOD | LSHIFT | RSHIFT | AMPERSAND | BIT_CLEAR) unaryExpr | unaryExpr ;\n\nunaryExpr --> (PLUS | MINUS | EXCLAMATION | CARET | STAR | AMPERSAND | RECEIVE) unaryExpr | primaryExpr ;\n\n# ANTLR: (operand | conversion | methodExpr) chosen by symbol-table predicates,\n# then a flat list of suffixes. methodExpr is dropped (\'T.m\' and \'(*T).m\' parse\n# as selectors), conversion is limited to types that cannot be expressions, and\n# explicit type arguments are the suffix instantiation.\nprimaryExpr --> (operand | conversion) (DOT IDENTIFIER | index | slice_ | typeAssertion | arguments | instantiation)* ;\n\nconversion --> conversionType L_PAREN expression COMMA? R_PAREN ;\n\n# Not in the ANTLR grammar: a type that cannot also be read as an expression,\n# so \'T(x)\' and \'(*T)(x)\' stay calls. A leading \'*\' or \'<-\' would be read as a\n# unary operator, so those types must be parenthesised.\nconversionType --> bareType | L_PAREN nonExprType R_PAREN ;\n\nbareType --> arrayType | structType | functionType | interfaceType | sliceType | mapType | CHAN chanElementType | CHAN RECEIVE elementType ;\n\nnonExprType --> bareType | STAR nonExprType | RECEIVE CHAN elementType | L_PAREN nonExprType R_PAREN ;\n\n# Explicit type arguments: two or more types, or one type that cannot be an\n# expression (\'f[T]\' with one type name is an index).\ninstantiation --> L_BRACKET (type_ COMMA typeList | nonExprType) COMMA? R_BRACKET ;\n\noperand --> literal | operandName | L_PAREN expression R_PAREN ;\n\nliteral --> basicLit | compositeLit | functionLit ;\n\nbasicLit --> NIL_LIT | integer | string_ | FLOAT_LIT ;\n\ninteger --> DECIMAL_LIT | BINARY_LIT | OCTAL_LIT | HEX_LIT | IMAGINARY_LIT | RUNE_LIT ;\n\noperandName --> IDENTIFIER ;\n\nqualifiedIdent --> IDENTIFIER DOT IDENTIFIER ;\n\ncompositeLit --> literalType literalValue ;\n\nliteralType --> structType | arrayType | L_BRACKET ELLIPSIS R_BRACKET elementType | sliceType | mapType | typeName typeArgs? ;\n\nliteralValue --> L_CURLY (elementList COMMA?)? R_CURLY ;\n\nelementList --> keyedElement (COMMA keyedElement)* ;\n\nkeyedElement --> (key COLON)? element ;\n\nkey --> expression | literalValue ;\n\nelement --> expression | literalValue ;\n\nstructType --> STRUCT L_CURLY (fieldDecl eos)* R_CURLY ;\n\nfieldDecl --> (identifierList type_ | embeddedField) string_? ;\n\nstring_ --> RAW_STRING_LIT | INTERPRETED_STRING_LIT ;\n\nembeddedField --> STAR? typeName typeArgs? ;\n\nfunctionLit --> FUNC signature block ;\n\nindex --> L_BRACKET expression R_BRACKET ;\n\nslice_ --> L_BRACKET (expression? COLON expression? | expression? COLON expression COLON expression) R_BRACKET ;\n\ntypeAssertion --> DOT L_PAREN type_ R_PAREN ;\n\n# ANTLR admits a leading type argument only after make or new (isTypeArgument).\n# Here a leading type is admitted after any callee, but only a type that cannot\n# be an expression; \'new(T)\' parses T as an expression.\narguments --> L_PAREN ((expressionList | nonExprType (COMMA expressionList)?) ELLIPSIS? COMMA?)? R_PAREN ;\n',
    'inputs.txt': 'package p\\nvar x = 1\npackage p\\nfunc f() {\\nx := 10\\n*p\\n}\npackage p\\nfunc f() { x := 1 y := 2 }\npackage p\\nvar a = []int{\\n1,\\n2\\n}\npackage p /* c */; import ("a"; "b") // end\npackage p\\nfunc f() { return }\n',
