    'grammar.ug': '# Port of grammars-v4 inf/inf.g4 (commit 7df52be9), INF (Windows setup information) files.\n# Original grammar: Copyright (c) 2017, Tom Everett, BSD 3-Clause License.\n#\n# Line ends are EOL tokens, as in ANTLR, so only blanks and tabs are whitespace.\n\nstart inf;\nwhitespace [ \\t]+;\nskip COMMENT;\n\ninf --> (section | EOL)* ;\n\nsection --> sectionheader line* ;\n\nsectionheader --> \'[\' string \']\' EOL ;\n\nstring --> CHARS | STRING ;\n\nline --> stringlist (\'=\' stringlist)? EOL ;\n\nstringlist --> string (\',\' string?)* ;\n\nCHARS --> [A-Za-z0-9.%"\\\\/*@&_{}<>\\-]+ ;\n\n# ANTLR lets CHARS win ties (first rule). A quoted string made only of CHARS\n# characters is matched by CHARS at equal or greater length, so STRING only\n# matches quoted text containing at least one character CHARS cannot match.\nSTRING --> (?="[^"\\n]*[^A-Za-z0-9.%"\\\\/*@&_{}<>\\-\\n])\'"\' [^"\\n]* \'"\' ;\n\n# As in ANTLR, a comment includes the line break that ends it.\nCOMMENT --> \';\' [^\\r\\n]* [\\r\\n]+ ;\n\nEOL --> [\\r\\n]+ ;\n',
