    'grammar.ug': '# Java (up to Java 21 syntax), ported from ANTLR grammars-v4\n# Source: java/java/JavaLexer.g4 and java/java/JavaParser.g4 at grammars-v4 commit 7df52be9\n# Copyright (c) 2013 Terence Parr, Sam Harwell; (c) 2017 Ivan Kochurkin;\n# (c) 2021, 2022 Michal Lorek. BSD licence (3-clause), see NOTICE.md.\n#\n# ANTLR resolves the grammar\'s ambiguities by alternative order and greedy\n# loops. This port is an Earley grammar, so it rewrites the expression rule into\n# precedence levels and uses production costs where ANTLR relies on order\n# (see NOTICE.md, Deviations):\n#   - a cast costs 1, so `(a) - b` is a subtraction (ANTLR picks the\n#     parenthesised primary, its first alternative);\n#   - annotations cost 0 as modifiers, 1 as interface method modifiers, 2 in\n#     front of an interface method\'s return type and 3 as type annotations at\n#     the start of a type, so each one goes to the earliest loop that can take\n#     it (ANTLR\'s greedy loops); interface method modifiers that are also\n#     general modifiers cost 1 for the same reason;\n#   - `T::m` as a type reference costs 1 against the expression reading;\n#   - a switch expression costs 2 and an arrow-form switch statement 1, so the\n#     classic switch statement wins and `switch (...) {...};` stays a statement;\n#   - `yield` as an identifier costs 1, so `yield -1;` is a yield statement;\n#   - a switch rule outcome that is a list of block statements costs 1, so a\n#     braced outcome is a block.\n# Feature `open` on statements resolves the dangling else.\n\nstart compilationunit;\nwhitespace [ \\t\\r\\n\\u000C]+;\nskip COMMENT, LINE_COMMENT;\n\ncompilationunit --> packageDeclaration? (importDeclaration | \';\')*\n                 | packageDeclaration? (importDeclaration | \';\')* typeDeclaration (typeDeclaration | \';\')*\n                 | modularCompulationUnit ;\n\nmodularCompulationUnit --> importDeclaration* moduleDeclaration ;\n\npackageDeclaration --> annotation* \'package\' qualifiedName \';\' ;\n\nimportDeclaration --> \'import\' \'static\'? qualifiedName (\'.\' \'*\')? \';\' ;\n\ntypeDeclaration --> classOrInterfaceModifier*\n    (classDeclaration | enumDeclaration | interfaceDeclaration | annotationTypeDeclaration | recordDeclaration) ;\n\nmodifier --> classOrInterfaceModifier | \'native\' | \'synchronized\' | \'transient\' | \'volatile\' ;\n\nclassOrInterfaceModifier --> annotation\n                          | \'public\'\n                          | \'protected\'\n                          | \'private\'\n                          | \'static\'\n                          | \'abstract\'\n                          | \'final\'\n                          | \'strictfp\'\n                          | \'sealed\'\n                          | \'non-sealed\' ;\n\nvariableModifier --> \'final\' | annotation ;\n\nclassDeclaration --> \'class\' identifier typeParameters? (\'extends\' typeType)? (\'implements\' typeList)? (\'permits\' typeList)? classBody ;\n\ntypeParameters --> \'<\' typeParameter (\',\' typeParameter)* \'>\' ;\n\ntypeParameter --> annotation* identifier (\'extends\' annotation* typeBound)? ;\n\ntypeBound --> typeType (\'&\' typeType)* ;\n\nenumDeclaration --> \'enum\' identifier (\'implements\' typeList)? \'{\' enumConstants? \',\'? enumBodyDeclarations? \'}\' ;\n\nenumConstants --> enumConstant (\',\' enumConstant)* ;\n\nenumConstant --> annotation* identifier arguments? classBody? ;\n\nenumBodyDeclarations --> \';\' classBodyDeclaration* ;\n\ninterfaceDeclaration --> \'interface\' identifier typeParameters? (\'extends\' typeList)? (\'permits\' typeList)? interfaceBody ;\n\nclassBody --> \'{\' classBodyDeclaration* \'}\' ;\ninterfaceBody --> \'{\' interfaceBodyDeclaration* \'}\' ;\n\nclassBodyDeclaration --> \';\' | \'static\'? block | modifier* memberDeclaration ;\n\nmemberDeclaration --> recordDeclaration\n                   | methodDeclaration\n                   | genericMethodDeclaration\n                   | fieldDeclaration\n                   | constructorDeclaration\n                   | genericConstructorDeclaration\n                   | interfaceDeclaration\n                   | annotationTypeDeclaration\n                   | classDeclaration\n                   | enumDeclaration ;\n\nmethodDeclaration --> typeTypeOrVoid identifier formalParameters (\'[\' \']\')* (\'throws\' qualifiedNameList)? methodBody ;\n\nmethodBody --> block | \';\' ;\n\ntypeTypeOrVoid --> typeType | \'void\' ;\n\ngenericMethodDeclaration --> typeParameters methodDeclaration ;\ngenericConstructorDeclaration --> typeParameters constructorDeclaration ;\n\nconstructorDeclaration --> identifier formalParameters (\'throws\' qualifiedNameList)? block ;\n\ncompactConstructorDeclaration --> modifier* identifier block ;\n\nfieldDeclaration --> typeType variableDeclarators \';\' ;\n\ninterfaceBodyDeclaration --> modifier* interfaceMemberDeclaration | \';\' ;\n\ninterfaceMemberDeclaration --> recordDeclaration\n                            | constDeclaration\n                            | interfaceMethodDeclaration\n                            | genericInterfaceMethodDeclaration\n                            | interfaceDeclaration\n                            | annotationTypeDeclaration\n                            | classDeclaration\n                            | enumDeclaration ;\n\nconstDeclaration --> typeType constantDeclarator (\',\' constantDeclarator)* \';\' ;\n\nconstantDeclarator --> identifier (\'[\' \']\')* \'=\' variableInitializer ;\n\ninterfaceMethodDeclaration --> interfaceMethodModifier* interfaceCommonBodyDeclaration ;\n\n# Modifiers that `modifier` also accepts cost 1, so ANTLR\'s greedy\n# interfaceBodyDeclaration `modifier*` loop takes them.\ninterfaceMethodModifier --> annotation @1 ;\ninterfaceMethodModifier --> \'public\' @1 ;\ninterfaceMethodModifier --> \'abstract\' @1 ;\ninterfaceMethodModifier --> \'default\' ;\ninterfaceMethodModifier --> \'static\' @1 ;\ninterfaceMethodModifier --> \'strictfp\' @1 ;\n\ngenericInterfaceMethodDeclaration --> interfaceMethodModifier* typeParameters interfaceCommonBodyDeclaration ;\n\ninterfaceCommonBodyDeclaration --> typeTypeOrVoid identifier formalParameters (\'[\' \']\')* (\'throws\' qualifiedNameList)? methodBody ;\ninterfaceCommonBodyDeclaration --> annotation+ typeTypeOrVoid identifier formalParameters (\'[\' \']\')* (\'throws\' qualifiedNameList)? methodBody @2 ;\n\nvariableDeclarators --> variableDeclarator (\',\' variableDeclarator)* ;\n\nvariableDeclarator --> variableDeclaratorId (\'=\' variableInitializer)? ;\n\nvariableDeclaratorId --> identifier (\'[\' \']\')* ;\n\nvariableInitializer --> arrayInitializer | expression ;\n\narrayInitializer --> \'{\' (variableInitializer (\',\' variableInitializer)* \',\'?)? \'}\' ;\n\n# ANTLR: ((packageName \'.\' annotation*)? typeIdentifier typeArguments?)+ (\'.\' annotation* typeIdentifier typeArguments?)*\nclassType --> typeIdentifier typeArguments?\n           | classTypePrefix \'.\' annotation* typeIdentifier typeArguments? ;\n\n# Leading segments are identifiers (package names may be `var`, `record`, ...),\n# the last one a typeIdentifier.\nclassTypePrefix --> identifier typeArguments?\n                 | classTypePrefix \'.\' annotation* identifier typeArguments? ;\n\ntypeArgument --> typeType | annotation* \'?\' ((\'extends\' | \'super\') typeType)? ;\n\nqualifiedNameList --> qualifiedName (\',\' qualifiedName)* ;\n\nformalParameters --> \'(\' ((receiverParameter | formalParameter) (\',\' formalParameterList)?)? \')\' ;\n\nreceiverParameter --> typeType \'this\' | typeType qualifiedName \'.\' \'this\' ;\n\nformalParameterList --> formalParameter (\',\' formalParameter)* ;\n\nformalParameter --> variableModifier* typeType (annotation* \'...\')? variableDeclaratorId ;\n\nlambdaLVTIList --> lambdaLVTIParameter (\',\' lambdaLVTIParameter)* ;\n\nlambdaLVTIParameter --> variableModifier* \'var\' identifier ;\n\nqualifiedName --> identifier (\'.\' identifier)* ;\n\nliteral --> integerLiteral\n         | floatLiteral\n         | CHAR_LITERAL\n         | STRING_LITERAL\n         | BOOL_LITERAL\n         | NULL_LITERAL\n         | TEXT_BLOCK ;\n\nintegerLiteral --> DECIMAL_LITERAL | HEX_LITERAL | OCT_LITERAL | BINARY_LITERAL ;\n\nfloatLiteral --> FLOAT_LITERAL | HEX_FLOAT_LITERAL ;\n\nannotation --> \'@\' qualifiedName annotationFieldValues? ;\n\nannotationFieldValues --> \'(\' (annotationFieldValue (\',\' annotationFieldValue)*)? \')\' ;\n\nannotationFieldValue --> annotationValue | identifier \'=\' annotationValue ;\n\nannotationValue --> conditionalExpression | annotation | \'{\' (annotationValue (\',\' annotationValue)*)? \',\'? \'}\' ;\n\nelementValue --> expression | annotation | elementValueArrayInitializer ;\n\nelementValueArrayInitializer --> \'{\' (elementValue (\',\' elementValue)*)? \',\'? \'}\' ;\n\nannotationTypeDeclaration --> \'@\' \'interface\' identifier annotationTypeBody ;\n\nannotationTypeBody --> \'{\' annotationTypeElementDeclaration* \'}\' ;\n\nannotationTypeElementDeclaration --> modifier* annotationTypeElementRest | \';\' ;\n\nannotationTypeElementRest --> typeType annotationMethodOrConstantRest \';\'\n                           | classDeclaration\n                           | interfaceDeclaration\n                           | enumDeclaration\n                           | annotationTypeDeclaration\n                           | recordDeclaration ;\n\nannotationMethodOrConstantRest --> annotationMethodRest | annotationConstantRest ;\n\nannotationMethodRest --> identifier \'(\' \')\' defaultValue? ;\n\nannotationConstantRest --> variableDeclarators ;\n\ndefaultValue --> \'default\' elementValue ;\n\nmoduleDeclaration --> annotation* \'open\'? \'module\' qualifiedName \'{\' moduleDirective* \'}\' ;\n\nmoduleDirective --> \'requires\' requiresModifier* qualifiedName \';\'\n                 | \'exports\' qualifiedName (\'to\' qualifiedName (\',\' qualifiedName)*)? \';\'\n                 | \'opens\' qualifiedName (\'to\' qualifiedName (\',\' qualifiedName)*)? \';\'\n                 | \'uses\' qualifiedName \';\'\n                 | \'provides\' qualifiedName \'with\' qualifiedName (\',\' qualifiedName)* \';\' ;\n\nrequiresModifier --> \'transitive\' | \'static\' ;\n\nrecordDeclaration --> \'record\' identifier typeParameters? recordHeader (\'implements\' typeList)? recordBody ;\n\nrecordHeader --> \'(\' recordComponentList? \')\' ;\n\nrecordComponentList --> recordComponent (\',\' recordComponent)* ;\n\nrecordComponent --> annotation* typeType (annotation* \'...\')? identifier ;\n\nrecordBody --> \'{\' (classBodyDeclaration | compactConstructorDeclaration)* \'}\' ;\n\nblock --> \'{\' blockStatement* \'}\' ;\n\nblockStatement --> localVariableDeclaration \';\' | localTypeDeclaration | statement ;\n\nlocalVariableDeclaration --> variableModifier* (\'var\' identifier \'=\' expression | typeType variableDeclarators) ;\n\nidentifier --> IDENTIFIER\n            | \'module\'\n            | \'open\'\n            | \'requires\'\n            | \'exports\'\n            | \'opens\'\n            | \'to\'\n            | \'uses\'\n            | \'provides\'\n            | \'when\'\n            | \'with\'\n            | \'transitive\' ;\n# Costs 1 so that `yield -1;` is a yield statement (ANTLR: alternative order).\nidentifier --> \'yield\' @1 ;\nidentifier --> \'sealed\' | \'permits\' | \'record\' | \'var\' ;\n\ntypeIdentifier --> IDENTIFIER\n                | \'module\'\n                | \'open\'\n                | \'requires\'\n                | \'exports\'\n                | \'opens\'\n                | \'to\'\n                | \'uses\'\n                | \'provides\'\n                | \'with\'\n                | \'transitive\'\n                | \'sealed\' ;\n\nlocalTypeDeclaration --> classOrInterfaceModifier* (classDeclaration | interfaceDeclaration | recordDeclaration | enumDeclaration) ;\n\n# ----------------------------------------------------------------- statements\n\nstatement{open: no} --> block | \'assert\' expression (\':\' expression)? \';\' ;\nstatement{open: yes} --> \'if\' \'(\' expression \')\' statement ;\nstatement{open: \$X} --> \'if\' \'(\' expression \')\' statement{open: no} \'else\' statement{open: \$X}\n                    | \'for\' \'(\' forControl \')\' statement{open: \$X}\n                    | \'while\' \'(\' expression \')\' statement{open: \$X} ;\nstatement{open: no} --> \'do\' statement \'while\' \'(\' expression \')\' \';\'\n                     | \'try\' block (catchClause+ finallyBlock? | finallyBlock)\n                     | \'try\' resourceSpecification block catchClause* finallyBlock?\n                     | \'switch\' \'(\' expression \')\' \'{\' switchBlockStatementGroup* switchLabel* \'}\'\n                     | \'synchronized\' \'(\' expression \')\' block\n                     | \'return\' expression? \';\'\n                     | \'throw\' expression \';\'\n                     | \'break\' identifier? \';\'\n                     | \'continue\' identifier? \';\'\n                     | \'yield\' expression \';\'\n                     | \';\'\n                     | expression \';\' ;\n# ANTLR: switchExpression \';\'?  The optional \';\' is an empty statement here.\nstatement{open: no} --> \'switch\' \'(\' expression \')\' \'{\' switchLabeledRule* \'}\' @1 ;\nstatement{open: \$X} --> identifier \':\' statement{open: \$X} ;\n\ncatchClause --> \'catch\' \'(\' variableModifier* catchType identifier \')\' block ;\n\ncatchType --> qualifiedName (\'|\' qualifiedName)* ;\n\nfinallyBlock --> \'finally\' block ;\n\nresourceSpecification --> \'(\' resources \';\'? \')\' ;\n\nresources --> resource (\';\' resource)* ;\n\nresource --> variableModifier* (classOrInterfaceType variableDeclaratorId | \'var\' identifier) \'=\' expression | qualifiedName ;\n\nswitchBlockStatementGroup --> switchLabel+ blockStatement+ ;\n\n# ANTLR: (switchLabel \':\')+ in groups and a trailing switchLabel* without \':\'.\n# The \':\' moves into switchLabel. The IDENTIFIER alternative is covered by\n# expression and dropped.\nswitchLabel --> \'case\' expression \':\' | \'case\' typeType identifier \':\' | \'default\' \':\' ;\n\nforControl --> enhancedForControl | forInit? \';\' expression? \';\' expressionList? ;\n\nforInit --> localVariableDeclaration | expressionList ;\n\nenhancedForControl --> variableModifier* (typeType | \'var\') variableDeclaratorId \':\' expression ;\n\nexpressionList --> expression (\',\' expression)* ;\n\nmethodCall --> (identifier | \'this\' | \'super\') arguments ;\n\n# ---------------------------------------------------------------- expressions\n# ANTLR\'s left-recursive `expression` rule, rewritten as precedence levels in\n# ANTLR\'s order (earlier alternatives bind tighter).\n\nexpression --> lambdaExpression | assignmentExpression ;\n\nassignmentExpression --> conditionalExpression ;\nassignmentExpression --> conditionalExpression\n    (\'=\' | \'+=\' | \'-=\' | \'*=\' | \'/=\' | \'&=\' | \'|=\' | \'^=\' | \'>>=\' | \'>>>=\' | \'<<=\' | \'%=\') expression ;\n\nconditionalExpression --> conditionalOrExpression\n                       | conditionalOrExpression \'?\' expression \':\' (conditionalExpression | lambdaExpression) ;\n\nconditionalOrExpression --> conditionalAndExpression\n                         | conditionalOrExpression \'||\' conditionalAndExpression ;\n\nconditionalAndExpression --> inclusiveOrExpression\n                          | conditionalAndExpression \'&&\' inclusiveOrExpression ;\n\ninclusiveOrExpression --> exclusiveOrExpression | inclusiveOrExpression \'|\' exclusiveOrExpression ;\n\nexclusiveOrExpression --> andExpression | exclusiveOrExpression \'^\' andExpression ;\n\nandExpression --> equalityExpression | andExpression \'&\' equalityExpression ;\n\nequalityExpression --> instanceofExpression\n                    | equalityExpression (\'==\' | \'!=\') instanceofExpression ;\n\ninstanceofExpression --> relationalExpression\n                      | instanceofExpression \'instanceof\' (typeType | pattern) ;\n\n# Not left-recursive: `a < b > c` would make `List<String> x = y;` an\n# expression statement too.\nrelationalExpression --> shiftExpression\n                      | shiftExpression (\'<=\' | \'>=\' | \'>\' | \'<\') shiftExpression ;\n\nshiftExpression --> additiveExpression\n                 | shiftExpression \'<\' \'<\' additiveExpression\n                 | shiftExpression \'>\' \'>\' \'>\' additiveExpression\n                 | shiftExpression \'>\' \'>\' additiveExpression ;\n\nadditiveExpression --> multiplicativeExpression\n                    | additiveExpression (\'+\' | \'-\') multiplicativeExpression ;\n\nmultiplicativeExpression --> unaryExpression\n                          | multiplicativeExpression (\'*\' | \'/\' | \'%\') unaryExpression ;\n\nunaryExpression --> (\'+\' | \'-\' | \'++\' | \'--\' | \'~\' | \'!\') unaryExpression\n                 | castExpression\n                 | \'new\' arrayCreator\n                 | postfixExpression ;\n\ncastExpression --> \'(\' annotation* typeBound \')\' (unaryExpression | lambdaExpression) @1 ;\n\npostfixExpression --> primary\n                   | methodCall\n                   | postfixExpression \'[\' expression \']\'\n                   | postfixExpression \'.\' (identifier | methodCall | \'this\' | explicitGenericInvocation)\n                   | postfixExpression \'.\' \'new\' nonWildcardTypeArguments? innerCreator\n                   | postfixExpression \'.\' \'super\' superSuffix\n                   | postfixExpression \'::\' typeArguments? identifier ;\npostfixExpression --> typeType \'::\' typeArguments? identifier @1 ;\npostfixExpression --> typeType \'::\' \'new\'\n                   | classType \'::\' typeArguments \'new\'\n                   | postfixExpression (\'++\' | \'--\') ;\n\npattern --> variableModifier* typeType annotation* identifier\n         | typeType \'(\' componentPatternList? \')\' ;\n\ncomponentPatternList --> componentPattern (\',\' componentPattern)* ;\n\ncomponentPattern --> pattern ;\n\nlambdaExpression --> lambdaParameters \'->\' lambdaBody ;\n\nlambdaParameters --> identifier | \'(\' (formalParameterList | identifier (\',\' identifier)* | lambdaLVTIList)? \')\' ;\n\nlambdaBody --> expression | block ;\n\nprimary --> \'(\' expression \')\'\n         | \'this\'\n         | \'super\'\n         | literal\n         | identifier\n         | typeTypeOrVoid \'.\' \'class\'\n         | nonWildcardTypeArguments (explicitGenericInvocationSuffix | \'this\' arguments)\n         | \'new\' creator\n         | switchExpression ;\n\nswitchExpression --> \'switch\' \'(\' expression \')\' \'{\' switchLabeledRule* \'}\' @2 ;\n\nswitchLabeledRule --> \'case\' (expressionList | NULL_LITERAL \',\' \'default\' | casePattern (\',\' casePattern)* guard?) (\'->\' | \':\') switchRuleOutcome\n                   | \'default\' (\'->\' | \':\') switchRuleOutcome ;\n\nguard --> \'when\' expression ;\n\ncasePattern --> pattern ;\n\nswitchRuleOutcome --> block ;\nswitchRuleOutcome --> blockStatement* @1 ;\n\nclassOrInterfaceType --> classType ;\n\ncreator --> nonWildcardTypeArguments? createdName classCreatorRest | createdName arrayCreatorRest ;\n\n# ANTLR\'s arrayCreatorRest alternative (\'[\' expression \']\')+ (\'[\' \']\')* is a\n# unary expression here, so `new int[2][3]` cannot also be read as an index.\narrayCreator --> createdName (\'[\' expression \']\')+ (\'[\' \']\')* ;\n\ncreatedName --> identifier typeArgumentsOrDiamond? (\'.\' identifier typeArgumentsOrDiamond?)* | primitiveType ;\n\ninnerCreator --> identifier nonWildcardTypeArgumentsOrDiamond? classCreatorRest ;\n\narrayCreatorRest --> (\'[\' \']\')+ arrayInitializer ;\n\nclassCreatorRest --> arguments classBody? ;\n\nexplicitGenericInvocation --> nonWildcardTypeArguments explicitGenericInvocationSuffix ;\n\ntypeArgumentsOrDiamond --> \'<\' \'>\' | typeArguments ;\n\nnonWildcardTypeArgumentsOrDiamond --> \'<\' \'>\' | nonWildcardTypeArguments ;\n\nnonWildcardTypeArguments --> \'<\' typeList \'>\' ;\n\ntypeList --> typeType (\',\' typeType)* ;\n\ntypeType --> (classOrInterfaceType | primitiveType) (annotation* \'[\' \']\')* ;\ntypeType --> annotation+ (classOrInterfaceType | primitiveType) (annotation* \'[\' \']\')* @3 ;\n\nprimitiveType --> \'boolean\' | \'char\' | \'byte\' | \'short\' | \'int\' | \'long\' | \'float\' | \'double\' ;\n\ntypeArguments --> \'<\' typeArgument (\',\' typeArgument)* \'>\' ;\n\nsuperSuffix --> arguments | \'.\' typeArguments? identifier arguments? ;\n\nexplicitGenericInvocationSuffix --> \'super\' superSuffix | identifier arguments ;\n\narguments --> \'(\' expressionList? \')\' ;\n\n# -------------------------------------------------------------------- lexer\n\nDECIMAL_LITERAL --> (?:0|[1-9](?:_+[0-9](?:[0-9_]*[0-9])?|(?:[0-9](?:[0-9_]*[0-9])?)?))[lL]? ;\nHEX_LITERAL --> [0] [xX] [0-9a-fA-F] (?:[0-9a-fA-F_]*[0-9a-fA-F])? [lL]? ;\nOCT_LITERAL --> [0] [_]* [0-7] (?:[0-7_]*[0-7])? [lL]? ;\nBINARY_LITERAL --> [0] [bB] [01] (?:[01_]*[01])? [lL]? ;\n\nFLOAT_LITERAL --> (?:(?:[0-9](?:[0-9_]*[0-9])?[.](?:[0-9](?:[0-9_]*[0-9])?)?|[.][0-9](?:[0-9_]*[0-9])?)(?:[eE][+-]?[0-9](?:[0-9_]*[0-9])?)?[fFdD]?|[0-9](?:[0-9_]*[0-9])?(?:[eE][+-]?[0-9](?:[0-9_]*[0-9])?[fFdD]?|[fFdD])) ;\n\nHEX_FLOAT_LITERAL --> [0] [xX] (?:[0-9a-fA-F](?:[0-9a-fA-F_]*[0-9a-fA-F])?[.]?|(?:[0-9a-fA-F](?:[0-9a-fA-F_]*[0-9a-fA-F])?)?[.][0-9a-fA-F](?:[0-9a-fA-F_]*[0-9a-fA-F])?) [pP] [+-]? [0-9] (?:[0-9_]*[0-9])? [fFdD]? ;\n\nBOOL_LITERAL --> (?:true|false) ;\nNULL_LITERAL --> \'null\' ;\n\nCHAR_LITERAL --> [\'] (?:[^\'\\\\\\r\\n]|[\\\\](?:u005c)?[bstnfr"\'\\\\]|[\\\\](?:u005c)?(?:[0-3]?[0-7])?[0-7]|[\\\\]u+[0-9a-fA-F]{4}) [\'] ;\n\nSTRING_LITERAL --> ["] (?:[^"\\\\\\r\\n]|[\\\\](?:u005c)?[bstnfr"\'\\\\]|[\\\\](?:u005c)?(?:[0-3]?[0-7])?[0-7]|[\\\\]u+[0-9a-fA-F]{4})* ["] ;\n\n# ANTLR: \'"""\' [ \\t]* [\\r\\n] (. | EscapeSequence)*? \'"""\'\nTEXT_BLOCK --> \'"""\' [ \\t]* [\\r\\n] (?:[^"\\\\]|[\\\\][\\s\\S]|["](?!""))* \'"""\' ;\n\nCOMMENT --> \'/*\' (?:[^*]|[*]+[^*/])* [*]+ \'/\' ;\nLINE_COMMENT --> \'//\' [^\\r\\n]* ;\n\nIDENTIFIER --> (?!(?:abstract|assert|boolean|break|byte|case|catch|char|class|const|continue|default|do|double|else|enum|exports|extends|final|finally|float|for|goto|if|implements|import|instanceof|int|interface|long|module|native|new|open|opens|package|permits|private|protected|provides|public|record|requires|return|sealed|short|static|strictfp|super|switch|synchronized|this|throw|throws|to|transient|transitive|try|uses|var|void|volatile|when|while|with|yield|true|false|null)(?![a-zA-Z0-9\$_\\u0080-￿]))\n    (?:[a-zA-Z\$_]|[^\\u0000-\\u007F]) (?:[a-zA-Z0-9\$_]|[^\\u0000-\\u007F])* ;\n',
    'inputs.txt': 'class A { List<String> x; }\nclass A { void f() { if (a) if (b) x(); else y(); } }\nclass A { int f() { return (a) - b; } }\nclass A { Object f() { return (String) o; } }\nclass A { int x = 1 }\n/* c */ module m.n { requires transitive java.base; } // end\n',
