    'grammar.ug': '# Port of grammars-v4 json5/JSON5.g4 (commit 7df52be9).\n# Source grammar: Student Main, 2020-07-22, public domain (as stated in the .g4 header).\n# Derived from grammars-v4 json/JSON.g4. See NOTICE.md for deviations.\n# Fragments (DOUBLE_QUOTE_CHAR, SINGLE_QUOTE_CHAR, ESCAPE_SEQUENCE, HEX, INT, EXP,\n# IDENTIFIER_START, IDENTIFIER_PART, UNICODE_SEQUENCE, NEWLINE) are inlined into the regexes.\n\nstart json5;\nwhitespace [ \\t\\n\\r\\u00A0\\uFEFF\\u2003]+;\nskip SINGLE_LINE_COMMENT, MULTI_LINE_COMMENT;\n\njson5 --> value?;\n\nobj --> \'{\' pair (\',\' pair)* \',\'? \'}\' | \'{\' \'}\';\n\npair --> key \':\' value;\n\nkey --> STRING | IDENTIFIER | LITERAL | NUMERIC_LITERAL;\n\nvalue --> STRING | number | obj | arr | LITERAL;\n\narr --> \'[\' value (\',\' value)* \',\'? \']\' | \'[\' \']\';\n\nnumber --> SYMBOL? (NUMERIC_LITERAL | NUMBER);\n\n# Lexer\n\n# the line terminator is part of the comment, as in ANTLR\nSINGLE_LINE_COMMENT --> \'//\' [^\\r\\n\\u2028\\u2029]* (?:\\r\\n|[\\r\\n\\u2028\\u2029])?;\nMULTI_LINE_COMMENT --> \'/*\' (?:[^*]|[*]+[^*/])* [*]+ \'/\';\n\nLITERAL --> (?:true|false|null);\n\nSTRING --> \'"\' (?:[^"\\\\\\r\\n]|[\\\\](?:\\r\\n|[\\r\\n\\u2028\\u2029]|u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|[^1-9xu\\r\\n]))* \'"\'\n        | "\'" (?:[^\'\\\\\\r\\n]|[\\\\](?:\\r\\n|[\\r\\n\\u2028\\u2029]|u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|[^1-9xu\\r\\n]))* "\'";\n\n# hexadecimal first: Java regex alternation takes the first alternative that matches\nNUMBER --> (?:0[xX][0-9a-fA-F]+|(?:0|[1-9][0-9]*)(?:[.][0-9]*)?(?:[Ee][+-]?[0-9]*)?|[.][0-9]+(?:[Ee][+-]?[0-9]*)?);\n\nNUMERIC_LITERAL --> (?:Infinity|NaN);\n\nSYMBOL --> [+-];\n\n# ANTLR gives LITERAL and NUMERIC_LITERAL priority over IDENTIFIER by rule order; here the\n# negative lookahead keeps IDENTIFIER from matching those words.\nIDENTIFIER --> (?!(?:true|false|null|Infinity|NaN)(?![\\p{L}\\p{M}\\p{N}\\p{Pc}\$_\\u200C\\u200D\\\\])) (?:[\\p{L}\$_]|[\\\\]u[0-9a-fA-F]{4}) (?:[\\p{L}\\p{M}\\p{N}\\p{Pc}\$_\\u