    'grammar.ug': '# Lua 5.4, ported from grammars-v4 lua/LuaLexer.g4 and lua/LuaParser.g4\n# (commit 7df52be9). License: MIT. Author: Ken Domino (October 2023), based\n# on previous work of Kazunori Sakamoto and Alexander Alexeev. See NOTICE.md.\n#\n# The rules follow LuaParser.g4, except that the ANTLR parser\'s hand-unrolled\n# prefixexp/functioncall rules (written to avoid mutual left recursion) are\n# replaced by the left-recursive rules of the Lua reference manual, and the\n# flat exp rule by one level per Lua 5.4 precedence level.\n\nstart chunk;\nwhitespace [ \\t\\u000C\\r\\n]+;\nskip LONGCOMMENT, LINECOMMENT, SHEBANG;\n\nchunk --> block ;\n\nblock --> stat* retstat? ;\n\n# A statement that starts with \'(\' is the "ambiguous syntax" case of the Lua\n# manual: \'a = f\' followed by \'(g)()\' on the next line can be one call or two\n# statements. Lua (and ANTLR, greedily) reads one call; a soft constraint\n# with weight 1 makes the two-statement reading cost more.\nstat --> \';\' ;\nstat --> varlist:vars \'=\' explist where (!starts_with(vars, \'(\')):1 ;\nstat --> functioncall:call where (!starts_with(call, \'(\')):1 ;\nstat --> label\n      | \'break\'\n      | \'goto\' NAME\n      | \'do\' block \'end\'\n      | \'while\' exp \'do\' block \'end\'\n      | \'repeat\' block \'until\' exp\n      | \'if\' exp \'then\' block (\'elseif\' exp \'then\' block)* (\'else\' block)? \'end\'\n      | \'for\' NAME \'=\' exp \',\' exp (\',\' exp)? \'do\' block \'end\'\n      | \'for\' namelist \'in\' explist \'do\' block \'end\'\n      | \'function\' funcname funcbody\n      | \'local\' \'function\' NAME funcbody\n      | \'local\' attnamelist (\'=\' explist)? ;\n\nattnamelist --> NAME attrib (\',\' NAME attrib)* ;\n\nattrib --> \'<\' NAME \'>\' | ;\n\nretstat --> \'return\' explist? \';\'? ;\n\nlabel --> \'::\' NAME \'::\' ;\n\nfuncname --> NAME (\'.\' NAME)* (\':\' NAME)? ;\n\nvarlist --> var (\',\' var)* ;\n\nnamelist --> NAME (\',\' NAME)* ;\n\nexplist --> exp (\',\' exp)* ;\n\n# Precedence, lowest first (Lua 5.4 manual, section 3.4.8):\n# or; and; comparison; |; ~; &; << >>; .. (right); + -; * / // %;\n# unary not # - ~; ^ (right, binds tighter than unary on its left).\nexp --> exp \'or\' andexp | andexp ;\n\nandexp --> andexp \'and\' compareexp | compareexp ;\n\ncompareexp --> compareexp (\'<\' | \'>\' | \'<=\' | \'>=\' | \'~=\' | \'==\') borexp | borexp ;\n\nborexp --> borexp \'|\' bxorexp | bxorexp ;\n\nbxorexp --> bxorexp \'~\' bandexp | bandexp ;\n\nbandexp --> bandexp \'&\' shiftexp | shiftexp ;\n\nshiftexp --> shiftexp (\'<<\' | \'>>\') concatexp | concatexp ;\n\nconcatexp --> addexp \'..\' concatexp | addexp ;\n\naddexp --> addexp (\'+\' | \'-\') mulexp | mulexp ;\n\nmulexp --> mulexp (\'*\' | \'/\' | \'%\' | \'//\') unaryexp | unaryexp ;\n\nunaryexp --> (\'not\' | \'#\' | \'-\' | \'~\') unaryexp | powexp ;\n\npowexp --> simpleexp \'^\' unaryexp | simpleexp ;\n\nsimpleexp --> \'nil\'\n           | \'false\'\n           | \'true\'\n           | number\n           | string\n           | \'...\'\n           | functiondef\n           | prefixexp\n           | tableconstructor ;\n\nvar --> NAME | prefixexp \'[\' exp \']\' | prefixexp \'.\' NAME ;\n\nprefixexp --> var | functioncall | \'(\' exp \')\' ;\n\nfunctioncall --> prefixexp args | prefixexp \':\' NAME args ;\n\nargs --> \'(\' explist? \')\' | tableconstructor | string ;\n\nfunctiondef --> \'function\' funcbody ;\n\nfuncbody --> \'(\' parlist \')\' block \'end\' ;\n\n# lparser.c checks whether the next token is \')\', so parlist can be empty.\nparlist --> namelist (\',\' \'...\')? | \'...\' | ;\n\ntableconstructor --> \'{\' fieldlist? \'}\' ;\n\nfieldlist --> field (fieldsep field)* fieldsep? ;\n\nfield --> \'[\' exp \']\' \'=\' exp | NAME \'=\' exp | exp ;\n\nfieldsep --> (\',\' | \';\') ;\n\nnumber --> (INT | HEX | FLOAT | HEX_FLOAT) ;\n\nstring --> (NORMALSTRING | CHARSTRING | LONGSTRING) ;\n\n# ------------------------------------------------------------------ tokens\n\nNAME --> (?!(?:and|break|do|else|elseif|end|false|for|function|goto|if|in|local|nil|not|or|repeat|return|then|true|until|while)(?![A-Za-z0-9_]))[A-Za-z_][A-Za-z0-9_]* ;\n\n# EscapeSequence, DecimalEscape, HexEscape and UtfEscape fragments inlined.\nNORMALSTRING --> \'"\' (?:[\\\\](?:[abfnrtvz"\'|\$#\\\\]|\\r?\\n|[0-2][0-9][0-9]|[0-9][0-9]?|x[0-9a-fA-F][0-9a-fA-F]|u\\{[0-9a-fA-F]+\\})|[^\\\\"])* \'"\' ;\n\nCHARSTRING --> "\'" (?:[\\\\](?:[abfnrtvz"\'|\$#\\\\]|\\r?\\n|[0-2][0-9][0-9]|[0-9][0-9]?|x[0-9a-fA-F][0-9a-fA-F]|u\\{[0-9a-fA-F]+\\})|[^\\\\\'])* "\'" ;\n\n# Long brackets: ANTLR matches \'[\' \'=\'* \'[\' ... \']\' \'=\'* \']\' with a recursive\n# fragment that does not check the levels agree. Here each level 0 to 7 is\n# spelled out, so the closing bracket must have the same level as the opening\n# one and the body ends at the first such closing bracket. Levels above 7 are\n# not supported.\nLONGSTRING --> (?:\\[\\[[\\s\\S]*?\\]\\]|\\[=\\[[\\s\\S]*?\\]=\\]|\\[==\\[[\\s\\S]*?\\]==\\]|\\[===\\[[\\s\\S]*?\\]===\\]|\\[====\\[[\\s\\S]*?\\]====\\]|\\[=====\\[[\\s\\S]*?\\]=====\\]|\\[======\\[[\\s\\S]*?\\]======\\]|\\[=======\\[[\\s\\S]*?\\]=======\\]) ;\n\nINT --> [0-9]+ ;\n\nHEX --> \'0\' [xX] [0-9a-fA-F]+ ;\n\nFLOAT --> (?:[0-9]+[.][0-9]*(?:[eE][+-]?[0-9]+)?|[.][0-9]+(?:[eE][+-]?[0-9]+)?|[0-9]+[eE][+-]?[0-9]+) ;\n\nHEX_FLOAT --> \'0\' [xX] (?:[0-9a-fA-F]+[.][0-9a-fA-F]*(?:[pP][+-]?[0-9]+)?|[.][0-9a-fA-F]+(?:[pP][+-]?[0-9]+)?|[0-9a-fA-F]+[pP][+-]?[0-9]+) ;\n\n# COMMENT is matched by target-language code in ANTLR (LuaLexerBase.HandleComment).\n# A long comment is \'--\' followed by a long bracket (same levels as LONGSTRING);\n# any other \'--\' runs to the end of the line.\nLONGCOMMENT --> \'--\' (?:\\[\\[[\\s\\S]*?\\]\\]|\\[=\\[[\\s\\S]*?\\]=\\]|\\[==\\[[\\s\\S]*?\\]==\\]|\\[===\\[[\\s\\S]*?\\]===\\]|\\[====\\[[\\s\\S]*?\\]====\\]|\\[=====\\[[\\s\\S]*?\\]=====\\]|\\[======\\[[\\s\\S]*?\\]======\\]|\\[=======\\[[\\s\\S]*?\\]=======\\]) ;\nLINECOMMENT --> \'--\' (?!\\[=*\\[) [^\\n]* ;\n\n# ANTLR hides SHEBANG when its predicate IsLine1Col0 holds.\nSHEBANG --> \'#\' \'!\'? [^\\n]* where at_char_start() ;\n',
    'inputs.txt': 'x = 1\na = f\\n(g)()\n(f or g)()\ns = [==[ a ]] b ]==] --[[ c ]] -- d\nx = 2 ^ 3 ^ 2\ns = [=[ a ]==]\n',
  },
