                          "symbol": "expression"\n                                          },\n                                          {\n                                            "symbol": "THEN"\n                                          },\n                                          {\n                                            "symbol": "statement",\n                                            "children": [\n                                              {\n                                                "symbol": "unlabelledStatement",\n                                                "children": [\n                                                  {\n                                                    "symbol": "structuredStatement",\n                                                    "children": [\n                                                      {\n                                                        "symbol": "conditionalStatement",\n                                                        "children": [\n                                                          {\n                                                            "symbol": "ifStatement",\n                                                            "children": [\n                                                              {\n                                                                "symbol": "IF"\n                                                              },\n                                                              {\n                                                                "symbol": "expression"\n                                                              },\n                                                              {\n                                                                "symbol": "THEN"\n                                                              },\n                                                              {\n                              