    'grammar.ug': '# Pascal, ported from grammars-v4 pascal/pascal.g4 (commit 7df52be9).\n# License: BSD 3-clause, Copyright (c) 2013, Tom Everett. Adapted from pascal.g\n# by Hakki Dogusan, Piet Schoutteten and Marton Papp. See NOTICE.md.\n#\n# Keywords are case-insensitive (ANTLR option caseInsensitive = true): each\n# keyword is a lexical category written with case classes, and IDENT excludes\n# every keyword with a negative lookahead.\n\nstart program;\nwhitespace [ \\t\\r\\n]+;\nskip COMMENT_1, COMMENT_2;\n\nprogram --> programHeading INTERFACE? block DOT ;\n\nprogramHeading --> PROGRAM identifier (LPAREN identifierList RPAREN)? SEMI | UNIT identifier SEMI ;\n\nidentifier --> IDENT ;\n\nblock --> (labelDeclarationPart | constantDefinitionPart | typeDefinitionPart\n          | variableDeclarationPart | procedureAndFunctionDeclarationPart\n          | usesUnitsPart | IMPLEMENTATION)* compoundStatement ;\n\nusesUnitsPart --> USES identifierList SEMI ;\n\nlabelDeclarationPart --> LABEL label (COMMA label)* SEMI ;\n\nlabel --> unsignedInteger ;\n\nconstantDefinitionPart --> CONST (constantDefinition SEMI)+ ;\n\nconstantDefinition --> identifier EQUAL constant ;\n\nconstantChr --> CHR LPAREN unsignedInteger RPAREN ;\n\nconstant --> unsignedNumber\n          | sign unsignedNumber\n          | identifier\n          | sign identifier\n          | string\n          | constantChr ;\n\nunsignedNumber --> unsignedInteger | unsignedReal ;\n\nunsignedInteger --> NUM_INT ;\n\nunsignedReal --> NUM_REAL ;\n\nsign --> PLUS | MINUS ;\n\nbool_ --> TRUE | FALSE ;\n\nstring --> STRING_LITERAL ;\n\ntypeDefinitionPart --> TYPE (typeDefinition SEMI)+ ;\n\ntypeDefinition --> identifier EQUAL (type_ | functionType | procedureType) ;\n\nfunctionType --> FUNCTION formalParameterList? COLON resultType ;\n\nprocedureType --> PROCEDURE formalParameterList? ;\n\ntype_ --> simpleType | structuredType | pointerType ;\n\nsimpleType --> scalarType | subrangeType | typeIdentifier | stringtype ;\n\nscalarType --> LPAREN identifierList RPAREN ;\n\nsubrangeType --> constant DOTDOT constant ;\n\ntypeIdentifier --> identifier | (CHAR | BOOLEAN | INTEGER | REAL | STRING) ;\n\nstructuredType --> PACKED unpackedStructuredType | unpackedStructuredType ;\n\nunpackedStructuredType --> arrayType | recordType | setType | fileType ;\n\nstringtype --> STRING LBRACK (identifier | unsignedNumber) RBRACK ;\n\narrayType --> ARRAY LBRACK typeList RBRACK OF componentType\n           | ARRAY LBRACK2 typeList RBRACK2 OF componentType ;\n\ntypeList --> indexType (COMMA indexType)* ;\n\nindexType --> simpleType ;\n\ncomponentType --> type_ ;\n\nrecordType --> RECORD fieldList? END ;\n\nfieldList --> fixedPart (SEMI variantPart)? | variantPart ;\n\nfixedPart --> recordSection (SEMI recordSection)* ;\n\nrecordSection --> identifierList COLON type_ ;\n\nvariantPart --> CASE tag OF variant (SEMI variant)* ;\n\ntag --> identifier COLON typeIdentifier | typeIdentifier ;\n\nvariant --> constList COLON LPAREN fieldList RPAREN ;\n\nsetType --> SET OF baseType ;\n\nbaseType --> simpleType ;\n\nfileType --> FILE OF type_ | FILE ;\n\npointerType --> POINTER typeIdentifier ;\n\nvariableDeclarationPart --> VAR variableDeclaration (SEMI variableDeclaration)* SEMI ;\n\nvariableDeclaration --> identifierList COLON type_ ;\n\nprocedureAndFunctionDeclarationPart --> procedureOrFunctionDeclaration SEMI ;\n\nprocedureOrFunctionDeclaration --> procedureDeclaration | functionDeclaration ;\n\nprocedureDeclaration --> PROCEDURE identifier formalParameterList? SEMI block ;\n\nformalParameterList --> LPAREN formalParameterSection (SEMI formalParameterSection)* RPAREN ;\n\nformalParameterSection --> parameterGroup\n                        | VAR parameterGroup\n                        | FUNCTION parameterGroup\n                        | PROCEDURE parameterGroup ;\n\nparameterGroup --> identifierList COLON typeIdentifier ;\n\nidentifierList --> identifier (COMMA identifier)* ;\n\nconstList --> constant (COMMA constant)* ;\n\nfunctionDeclaration --> FUNCTION identifier formalParameterList? COLON resultType SEMI block ;\n\nresultType --> typeIdentifier ;\n\n# The dangling else, which ANTLR resolves greedily, is resolved by the grammar:\n# the then-branch of an if-then-else is a closedStatement, one that does not\n# end in an if-then without an else, so an else always binds to the nearest\n# if. Statements that can end in a nested statement (if, while, for, with,\n# labels) have closed counterparts.\nstatement --> label COLON unlabelledStatement | unlabelledStatement ;\n\nunlabelledStatement --> simpleStatement | structuredStatement ;\n\nclosedStatement --> label COLON closedUnlabelledStatement | closedUnlabelledStatement ;\n\nclosedUnlabelledStatement --> (simpleStatement | compoundStatement | caseStatement\n                              | repeatStatement | closedIfStatement | closedWhileStatement\n                              | closedForStatement | closedWithStatement) ;\n\nclosedIfStatement --> IF expression THEN closedStatement ELSE closedStatement ;\n\nclosedWhileStatement --> WHILE expression DO closedStatement ;\n\nclosedForStatement --> FOR identifier ASSIGN forList DO closedStatement ;\n\nclosedWithStatement --> WITH recordVariableList DO closedStatement ;\n\nsimpleStatement --> assignmentStatement | procedureStatement | gotoStatement | emptyStatement_ ;\n\nassignmentStatement --> variable ASSIGN expression ;\n\nvariable --> (AT identifier | identifier)\n             (LBRACK expression (COMMA expression)* RBRACK\n             | LBRACK2 expression (COMMA expression)* RBRACK2\n             | DOT identifier\n             | POINTER)* ;\n\n# The ANTLR rules are right recursive (a - b - c groups as a - (b - c)).\n# Rewritten left recursive so trees reflect Pascal\'s left associativity.\nexpression --> expression relationaloperator simpleExpression | simpleExpression ;\n\nrelationaloperator --> (EQUAL | NOT_EQUAL | LT | LE | GE | GT | IN) ;\n\nsimpleExpression --> simpleExpression additiveoperator term | term ;\n\nadditiveoperator --> (PLUS | MINUS | OR) ;\n\nterm --> term multiplicativeoperator signedFactor | signedFactor ;\n\nmultiplicativeoperator --> (STAR | SLASH | DIV | MOD | AND) ;\n\nsignedFactor --> (PLUS | MINUS)? factor ;\n\nfactor --> variable\n        | LPAREN expression RPAREN\n        | functionDesignator\n        | unsignedConstant\n        | set_\n        | NOT factor\n        | bool_ ;\n\nunsignedConstant --> unsignedNumber | constantChr | string | NIL ;\n\nfunctionDesignator --> identifier LPAREN parameterList RPAREN ;\n\nparameterList --> actualParameter (COMMA actualParameter)* ;\n\nset_ --> LBRACK elementList RBRACK | LBRACK2 elementList RBRACK2 ;\n\nelementList --> element (COMMA element)* | ;\n\nelement --> expression (DOTDOT expression)? ;\n\nprocedureStatement --> identifier (LPAREN parameterList RPAREN)? ;\n\nactualParameter --> expression parameterwidth* ;\n\nparameterwidth --> COLON expression ;\n\ngotoStatement --> GOTO label ;\n\nemptyStatement_ --> ;\n\nstructuredStatement --> compoundStatement\n                     | conditionalStatement\n                     | repetetiveStatement\n                     | withStatement ;\n\ncompoundStatement --> BEGIN statements END ;\n\nstatements --> statement (SEMI statement)* ;\n\nconditionalStatement --> ifStatement | caseStatement ;\n\nifStatement --> IF expression THEN statement | IF expression THEN closedStatement ELSE statement ;\n\ncaseStatement --> CASE expression OF caseListElement (SEMI caseListElement)* (SEMI ELSE statements)? END ;\n\ncaseListElement --> constList COLON statement ;\n\nrepetetiveStatement --> whileStatement | repeatStatement | forStatement ;\n\nwhileStatement --> WHILE expression DO statement ;\n\nrepeatStatement --> REPEAT statements UNTIL expression ;\n\nforStatement --> FOR identifier ASSIGN forList DO statement ;\n\nforList --> initialValue (TO | DOWNTO) finalValue ;\n\ninitialValue --> expression ;\n\nfinalValue --> expression ;\n\nwithStatement --> WITH recordVariableList DO statement ;\n\nrecordVariableList --> variable (COMMA variable)* ;\n\n# ------------------------------------------------------------------ tokens\n\nAND --> [Aa][Nn][Dd] ;\nARRAY --> [Aa][Rr][Rr][Aa][Yy] ;\nBEGIN --> [Bb][Ee][Gg][Ii][Nn] ;\nBOOLEAN --> [Bb][Oo][Oo][Ll][Ee][Aa][Nn] ;\nCASE --> [Cc][Aa][Ss][Ee] ;\nCHAR --> [Cc][Hh][Aa][Rr] ;\nCHR --> [Cc][Hh][Rr] ;\nCONST --> [Cc][Oo][Nn][Ss][Tt] ;\nDIV --> [Dd][Ii][Vv] ;\nDO --> [Dd][Oo] ;\nDOWNTO --> [Dd][Oo][Ww][Nn][Tt][Oo] ;\nELSE --> [Ee][Ll][Ss][Ee] ;\nEND --> [Ee][Nn][Dd] ;\nFILE --> [Ff][Ii][Ll][Ee] ;\nFOR --> [Ff][Oo][Rr] ;\nFUNCTION --> [Ff][Uu][Nn][Cc][Tt][Ii][Oo][Nn] ;\nGOTO --> [Gg][Oo][Tt][Oo] ;\nIF --> [Ii][Ff] ;\nIN --> [Ii][Nn] ;\nINTEGER --> [Ii][Nn][Tt][Ee][Gg][Ee][Rr] ;\nLABEL --> [Ll][Aa][Bb][Ee][Ll] ;\nMOD --> [Mm][Oo][Dd] ;\nNIL --> [Nn][Ii][Ll] ;\nNOT --> [Nn][Oo][Tt] ;\nOF --> [Oo][Ff] ;\nOR --> [Oo][Rr] ;\nPACKED --> [Pp][Aa][Cc][Kk][Ee][Dd] ;\nPROCEDURE --> [Pp][Rr][Oo][Cc][Ee][Dd][Uu][Rr][Ee] ;\nPROGRAM --> [Pp][Rr][Oo][Gg][Rr][Aa][Mm] ;\nREAL --> [Rr][Ee][Aa][Ll] ;\nRECORD --> [Rr][Ee][Cc][Oo][Rr][Dd] ;\nREPEAT --> [Rr][Ee][Pp][Ee][Aa][Tt] ;\nSET --> [Ss][Ee][Tt] ;\nTHEN --> [Tt][Hh][Ee][Nn] ;\nTO --> [Tt][Oo] ;\nTYPE --> [Tt][Yy][Pp][Ee] ;\nUNTIL --> [Uu][Nn][Tt][Ii][Ll] ;\nVAR --> [Vv][Aa][Rr] ;\nWHILE --> [Ww][Hh][Ii][Ll][Ee] ;\nWITH --> [Ww][Ii][Tt][Hh] ;\nUNIT --> [Uu][Nn][Ii][Tt] ;\nINTERFACE --> [Ii][Nn][Tt][Ee][Rr][Ff][Aa][Cc][Ee] ;\nUSES --> [Uu][Ss][Ee][Ss] ;\nSTRING --> [Ss][Tt][Rr][Ii][Nn][Gg] ;\nIMPLEMENTATION --> [Ii][Mm][Pp][Ll][Ee][Mm][Ee][Nn][Tt][Aa][Tt][Ii][Oo][Nn] ;\nTRUE --> [Tt][Rr][Uu][Ee] ;\nFALSE --> [Ff][Aa][Ll][Ss][Ee] ;\n\nIDENT --> (?!(?:[Ii][Mm][Pp][Ll][Ee][Mm][Ee][Nn][Tt][Aa][Tt][Ii][Oo][Nn]|[Pp][Rr][Oo][Cc][Ee][Dd][Uu][Rr][Ee]|[Ii][Nn][Tt][Ee][Rr][Ff][Aa][Cc][Ee]|[Ff][Uu][Nn][Cc][Tt][Ii][Oo][Nn]|[Bb][Oo][Oo][Ll][Ee][Aa][Nn]|[Ii][Nn][Tt][Ee][Gg][Ee][Rr]|[Pp][Rr][Oo][Gg][Rr][Aa][Mm]|[Dd][Oo][Ww][Nn][Tt][Oo]|[Pp][Aa][Cc][Kk][Ee][Dd]|[Rr][Ee][Cc][Oo][Rr][Dd]|[Rr][Ee][Pp][Ee][Aa][Tt]|[Ss][Tt][Rr][Ii][Nn][Gg]|[Aa][Rr][Rr][Aa][Yy]|[Bb][Ee][Gg][Ii][Nn]|[Cc][Oo][Nn][Ss][Tt]|[Ll][Aa][Bb][Ee][Ll]|[Uu][Nn][Tt][Ii][Ll]|[Ww][Hh][Ii][Ll][Ee]|[Ff][Aa][Ll][Ss][Ee]|[Cc][Aa][Ss][Ee]|[Cc][Hh][Aa][Rr]|[Ee][Ll][Ss][Ee]|[Ff][Ii][Ll][Ee]|[Gg][Oo][Tt][Oo]|[Rr][Ee][Aa][Ll]|[Tt][Hh][Ee][Nn]|[Tt][Yy][Pp][Ee]|[Ww][Ii][Tt][Hh]|[Uu][Nn][Ii][Tt]|[Uu][Ss][Ee][Ss]|[Tt][Rr][Uu][Ee]|[Aa][Nn][Dd]|[Cc][Hh][Rr]|[Dd][Ii][Vv]|[Ee][Nn][Dd]|[Ff][Oo][Rr]|[Mm][Oo][Dd]|[Nn][Ii][Ll]|[Nn][Oo][Tt]|[Ss][Ee][Tt]|[Vv][Aa][Rr]|[Dd][Oo]|[Ii][Ff]|[Ii][Nn]|[Oo][Ff]|[Oo][Rr]|[Tt][Oo])(?![A-Za-z0-9_]))[A-Za-z][A-Za-z0-9_]* ;\n\nPLUS --> \'+\' ;\nMINUS --> \'-\' ;\nSTAR --> \'*\' ;\nSLASH --> \'/\' ;\nASSIGN --> \':=\' ;\nCOMMA --> \',\' ;\nSEMI --> \';\' ;\nCOLON --> \':\' ;\nEQUAL --> \'=\' ;\nNOT_EQUAL --> \'<>\' ;\nLT --> \'<\' ;\nLE --> \'<=\' ;\nGE --> \'>=\' ;\nGT --> \'>\' ;\nLPAREN --> \'(\' ;\nRPAREN --> \')\' ;\nLBRACK --> \'[\' ;\nLBRACK2 --> \'(.\' ;\nRBRACK --> \']\' ;\nRBRACK2 --> \'.)\' ;\nPOINTER --> \'^\' ;\nAT --> \'@\' ;\nDOT --> \'.\' ;\nDOTDOT --> \'..\' ;\n\nCOMMENT_1 --> \'(*\' (?:[^*]|[*]+[^*\\)])* [*]+ \')\' ;\nCOMMENT_2 --> \'{\' [^}]* \'}\' ;\n\nSTRING_LITERAL --> "\'" (?:\'\'|[^\'])* "\'" ;\n\nNUM_INT --> [0-9]+ ;\n\n# ANTLR\'s NUM_REAL also matches a bare digit string (its fraction is optional),\n# which would tie with NUM_INT here; a fraction or an exponent is required.\nNUM_REAL --> [0-9]+ (?:[.][0-9]+(?:[eE][+-]?[0-9]+)?|[eE][+-]?[0-9]+) ;\n',
