    'grammar.ug': '# Prolog (ISO 13211-1 tokens and terms, single-level operator table).\n# Ported from grammars-v4 prolog/prolog.g4 (commit 7df52be9).\n# Copyright (c) 2013, Tom Everett. BSD licence (see NOTICE.md).\n#\n# ANTLR fragments are inlined into the token regexes.\n\nstart p_text;\nwhitespace [ \\t\\r\\n]+;\nskip COMMENT, MULTILINE_COMMENT;\n\np_text --> (directive | clause)* ;\n\ndirective --> \':-\' term \'.\' ;\n\n# A term starting with the prefix operator \':-\' would make every directive\n# also a clause. ANTLR takes the first alternative (directive); here the\n# clause reading is excluded by a constraint on the term\'s text.\nclause --> term:t \'.\' where !matches(t, \'(?s):-(?![#\$&*+./:<=>?@^~\\\\\\\\-]).*\') ;\n\n# Arguments are separated by \',\'. \',\' is also an operator, so an argument\n# is a term whose top-level binary operator is not \',\' (ISO priority 999).\ntermlist --> arg (\',\' arg)* ;\n\n# ANTLR\'s single left-recursive term rule with <assoc = right> becomes a\n# right-recursive operator chain over primary terms. A prefix operator\n# applies to the whole rest of the term, as in the ANTLR precedence order\n# (the binary alternative precedes the unary one).\nterm --> primary | primary operator_ term | operator_ term ;\n\narg --> primary ;\narg --> primary operator_:op arg where !matches(op, \',\') ;\narg --> operator_ arg ;\n\nprimary --> VARIABLE\n         | \'(\' term \')\'\n         | integer\n         | FLOAT\n         | atom \'(\' termlist \')\'\n         | \'[\' termlist (\'|\' term)? \']\'\n         | \'{\' termlist \'}\'\n         | atom ;\n\noperator_ --> \':-\'\n           | \'-->\'\n           | \'?-\'\n           | \'dynamic\'\n           | \'multifile\'\n           | \'discontiguous\'\n           | \'public\'\n           | \';\'\n           | \'->\'\n           | \',\'\n           | \'\\\\+\'\n           | \'=\'\n           | \'\\\\=\'\n           | \'==\'\n           | \'\\\\==\'\n           | \'@<\'\n           | \'@=<\'\n           | \'@>\'\n           | \'@>=\'\n           | \'=..\'\n           | \'is\'\n           | \'=:=\'\n           | \'=\\\\=\'\n           | \'<\'\n           | \'=<\'\n           | \'>\'\n           | \'>=\'\n           | \':\'\n           | \'+\'\n           | \'-\'\n           | \'/\\\\\'\n           | \'\\\\/\'\n           | \'*\'\n           | \'/\'\n           | \'//\'\n           | \'rem\'\n           | \'mod\'\n           | \'<<\'\n           | \'>>\'\n           | \'**\'\n           | \'^\'\n           | \'\\\\\' ;\n\natom --> \'[\' \']\'\n      | \'{\' \'}\'\n      | LETTER_DIGIT\n      | GRAPHIC_TOKEN\n      | QUOTED\n      | DOUBLE_QUOTED_LIST\n      | BACK_QUOTED_STRING\n      | \';\'\n      | \'!\' ;\n\ninteger --> DECIMAL | CHARACTER_CODE_CONSTANT | BINARY | OCTAL | HEX ;\n\n# Names start with a lower-case letter (ANTLR\'s SMALL_LETTER also admits\n# \'_\', which made \'_\' and \'_X\' atoms). The operator words are literal tokens\n# in ANTLR, which win over LETTER_DIGIT on equal length; here a lookahead\n# excludes them.\nLETTER_DIGIT --> (?!(?:dynamic|multifile|discontiguous|public|is|rem|mod)(?![A-Za-z0-9_]))[a-z][A-Za-z0-9_]* ;\n\nVARIABLE --> [A-Z_][A-Za-z0-9_]* ;\n\nDECIMAL --> [0-9]+ ;\nBINARY --> \'0b\' [01]+ ;\nOCTAL --> \'0o\' [0-7]+ ;\nHEX --> \'0x\' [0-9a-fA-F]+ ;\n\nCHARACTER_CODE_CONSTANT --> "0\'" (?:[#\$&*+./:<=>?@^~A-Za-z0-9_!\\(\\),;\\[\\]{}|% "`-]|\'\'|\\\\[\\\\\'"`abrftnv]|\\\\[0-7]+\\\\|\\\\x[0-9a-fA-F]+\\\\) ;\n\nFLOAT --> [0-9]+ \'.\' [0-9]+ (?:[eE][+-][0-9]+)? ;\n\n# Graphic tokens, except the operator and end tokens that ANTLR lexes as\n# literals (literals win over GRAPHIC_TOKEN on equal length in ANTLR).\nGRAPHIC_TOKEN --> (?!(?::-|-->|\\?-|->|\\\\\\+|=|\\\\=|==|\\\\==|@<|@=<|@>|@>=|=\\.\\.|=:=|=\\\\=|<|=<|>|>=|:|\\+|-|/\\\\|\\\\/|\\*|/|//|<<|>>|\\*\\*|\\^|\\\\|\\.)(?![#\$&*+./:<=>?@^~\\\\-]))[#\$&*+./:<=>?@^~\\\\-]+ ;\n\nQUOTED --> "\'" (?:[#\$&*+./:<=>?@^~A-Za-z0-9_!\\(\\),;\\[\\]{}|% "`-]|\'\'|\\\\[\\\\\'"`abrftnv]|