    'grammar.ug': '# Port of grammars-v4 rfc1035/domain.g4 (commit 7df52be9), RFC 1035 domain names.\n# Original grammar: Copyright (c) 2020, Tom Everett, BSD 3-Clause License.\n# The ANTLR lexer rules LDH_STR, LET_DIG_HYP, LET_DIG, LETTER and DIGIT are\n# inlined into LABEL; the parser never uses them on their own. See NOTICE.md.\n\nstart domain;\n\n# A single space is a domain of its own, so whitespace is never discarded.\nwhitespace none;\n\ndomain --> subdomain | \' \' ;\n\nsubdomain --> LABEL (\'.\' LABEL)* ;\n\n# <label> ::= <letter> [ [ <ldh-str> ] <let-dig> ]\nLABEL --> [a-zA-Z] (?:[a-zA-Z0-9\\-]*[a-zA-Z0-9])? ;\n',
