    'expected.json': '{\n  "grammar": {"ok": true},\n  "inputs": [\n    {\n      "input": "(a (b \\"c\\"))",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "sexpr", "children": [\n        {"symbol": "item", "children": [\n          {"symbol": "list_", "children": [\n            {"text": "(", "start": 0, "end": 1},\n            {"symbol": "item", "children": [\n              {"symbol": "atom", "children": [\n                {"symbol": "SYMBOL", "children": [{"text": "a", "start": 1, "end": 2}]}]}]},\n            {"symbol": "item", "children": [\n              {"symbol": "list_", "children": [\n                {"text": "(", "start": 3, "end": 4},\n                {"symbol": "item", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "SYMBOL", "children": [{"text": "b", "start": 4, "end": 5}]}]}]},\n                {"symbol": "item", "children": [\n                  {"symbol": "atom", "children": [\n                    {"symbol": "STRING", "children": [{"text": "\\"c\\"", "start": 6, "end": 9}]}]}]},\n                {"text": ")", "start": 9, "end": 10}]}]},\n            {"text": ")", "start": 10, "end": 11}]}]}]}\n    },\n    {\n      "input": "-1.5 -1.5x",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "sexpr", "children": [\n        {"symbol": "item", "children": [\n          {"symbol": "atom", "children": [\n            {"symbol": "NUMBER", "children": [{"text": "-1.5", "start": 0, "end": 4}]}]}]},\n        {"symbol": "item", "children": [\n          {"symbol": "atom", "children": [\n            {"symbol": "SYMBOL", "children": [{"text": "-1.5x", "start": 5, "end": 10}]}]}]}]}\n    },\n    {\n      "input": "(a . b)",\n      "outcome": "accepted", "penalty": 0, "ambiguous": false,\n      "tree": {"symbol": "sexpr", "children": [\n        {"symbol": "item", "children": [\n          {"symbol": "list_", "children": [\n            {"text":