    'grammar.ug': '# Lisp s-expressions: atoms (strings, numbers, symbols) and parenthesised lists.\n# Ported from grammars-v4 sexpression/sexpression.g4 (commit 7df52be9).\n# Copyright (c) 2008 Robert Stehwien, ported to ANTLR 4 by Tom Everett.\n# MIT licence (see NOTICE.md).\n#\n# The ANTLR grammar has a dotted-pair alternative (item : LPAREN item DOT item\n# RPAREN) and DOT as an atom, but its lexer never produces DOT: SYMBOL also\n# matches \'.\' and is declared first, so \'.\' is always a SYMBOL. Both are\n# omitted here; the accepted language is the same.\n\nstart sexpr;\nwhitespace [ \\n\\t\\r]+;\n\nsexpr --> item* ;\n\nitem --> atom | list_ ;\n\nlist_ --> \'(\' item* \')\' ;\n\natom --> STRING | SYMBOL | NUMBER ;\n\nSTRING --> \'"\' (?:[\\\\][\\s\\S]|[^\\\\"])* \'"\' ;\n\nNUMBER --> [+\\-]? [0-9]+ (?:[.][0-9]+)? ;\n\n# ANTLR declares NUMBER before SYMBOL, so a signed number such as \'-1.5\' is a\n# NUMBER although SYMBOL matches the same text. Equal-length matches are\n# alternatives here, so SYMBOL excludes exactly those texts.\nSYMBOL --> (?![+\\-][0-9]+(?:[.][0-9]+)?(?![a-zA-Z+\\-*/.0-9])) [a-zA-Z+\\-*/.] [a-zA-Z+\\-*/.0-9]* ;\n',
    'inputs.txt': '(a (b "c"))\n-1.5 -1.5x\n(a . b)\n\n(a "b)\n',
  },
