    'expected.json': '{\n  "grammar": {"ok": true},\n  "inputs": [\n    {\n      "input": "BEGIN WRITE 1-2 END",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {"symbol": "program", "children": [\n        {"text": "BEGIN", "start": 0, "end": 5},\n        {"symbol": "stmt_list", "children": [\n          {"symbol": "stmt", "children": [\n            {"symbol": "write_stmt", "children": [\n              {"text": "WRITE", "start": 6, "end": 11},\n              {"symbol": "expr_list", "children": [\n                {"symbol": "expr", "children": [\n                  {"symbol": "expr", "children": [\n                    {"symbol": "factor", "children": [\n                      {"symbol": "integer", "children": [\n                        {"symbol": "NUMBER", "children": [{"text": "1", "start": 12, "end": 13}]}]}]}]},\n                  {"symbol": "op", "children": [{"text": "-", "start": 13, "end": 14}]},\n                  {"symbol": "factor", "children": [\n                    {"symbol": "integer", "children": [\n                      {"symbol": "NUMBER", "children": [{"text": "2", "start": 14, "end": 15}]}]}]}]}]}]}]}]},\n        {"text": "END", "start": 16, "end": 19}]}\n    },\n    {\n      "input": "BEGIN READ a, b WRITE a - -1 END",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {"symbol": "program", "children": [\n        {"text": "BEGIN"},\n        {"symbol": "stmt_list", "children": [\n          {"symbol": "stmt_list", "children": [\n            {"symbol": "stmt", "children": [\n              {"symbol": "read_stmt", "children": [\n                {"text": "READ"},\n                {"symbol": "id_list", "children": [\n                  {"symbol": "id_list"},\n                  {"text": ",", "start": 12, "end": 13},\n                  {"symbol": "ident"}]}]}]}]},\n          {"symbol": "stmt", "children": [\n            {"symbol": "write_stmt", "children": [\n              {"text": "WRITE"},\n              {"symbol": "expr_list", "children": [\n                {"symbol": "expr", "children": [\n                  {"symbol": "expr"},\n                  {"symbol": "op", "children": [{"text": "-", "start": 24, "end": 25}]},\n                  {"symbol": "factor", "children": [\n                    {"symbol": "integer", "children": [\n                      {"text": "-", "start": 26, "end": 27},\n                      {"symbol": "NUMBER", "children": [{"text": "1", "start": 27, "end": 28}]}]}]}]}]}]}]}]},\n        {"text": "END", "start": 29, "end": 32}]}\n    },\n    {"input": "BEGIN x := y END", "outcome": "accepted", "penalty": 0, "ambiguous": false},\n    {"input": "BEGIN END", "outcome": "rejected"},\n    {"input": "BEGIN READ END END", "outcome": "rejected"}\n  ]\n}\n',
    'grammar.ug': '# TINY, a toy language with assignment, READ and WRITE statements.\n# Ported from grammars-v4 tiny/tiny.g4 (commit 7df52be9).\n# Copyright (c) 2016, Tom Everett. BSD licence (see NOTICE.md).\n#\n# The rules are those of tiny.g4, including its left-recursive lists.\n\nstart program;\nwhitespace [ \\r\\n]+;\n\nprogram --> \'BEGIN\' stmt_list \'END\' ;\n\nstmt_list --> stmt_list stmt | stmt ;\n\nstmt --> assign_stmt | read_stmt | write_stmt ;\n\nassign_stmt --> ident \':=\' expr ;\n\nread_stmt --> \'READ\' id_list ;\n\nwrite_stmt --> \'WRITE\' expr_list ;\n\nid_list --> id_list \',\' ident | ident ;\n\nexpr_list --> expr_list \',\' expr | expr ;\n\nexpr --> expr op factor | factor ;\n\nfactor --> ident | integer ;\n\ninteger --> \'-\'? NUMBER ;\n\n# A production whose right-hand side is a single literal is lexical, so op\n# is a token category here (a node with one leaf, the same tree shape as the\n# ANTLR parser rule).\nop --> \'+\' | \'-\' ;\n\nident --> ID ;\n\n# In ANTLR the implicit keyword tokens win over ID on equal length; here the\n# keywords are excluded from ID with a lookahead.\nID --> (?!(?:BEGIN|END|READ|WRITE)(?![a-zA-Z]))[a-zA-Z]+ ;\n\nNUMBER --> [0-9]+ ;\n',
    'inputs.txt': 'BEGIN WRITE 1-2 END\nBEGIN READ a, b WRITE a - -1 END\nBEGIN x := y END\nBEGIN END\nBEGIN READ END END\n',
  },
