"symbol": "statement", "children": [\n          {"symbol": "matched", "children": [\n            {"text": "{", "start": 0, "end": 1},\n            {"symbol": "statement", "children": [\n              {"symbol": "matched", "children": [\n                {"text": "while", "start": 2, "end": 7},\n                {"symbol": "paren_expr"},\n                {"symbol": "matched", "children": [\n                  {"symbol": "expr", "children": [\n                    {"symbol": "id_"},\n                    {"text": "=", "start": 15, "end": 16},\n                    {"symbol": "expr", "children": [\n                      {"symbol": "test", "children": [\n                        {"symbol": "sum_", "children": [\n                          {"symbol": "sum_"},\n                          {"text": "-", "start": 17, "end": 18},\n                          {"symbol": "term"}]}]}]}]},\n                  {"text": ";", "start": 19, "end": 20}]}]}]},\n            {"text": "}", "start": 21, "end": 22}]}]}]}\n    },\n    {"input": "if = 1;", "outcome": "rejected"},\n    {"input": "do ; while (x)", "outcome": "rejected"}\n  ]\n}\n',
    'grammar.ug': '# Tiny-C (Marc Feeley\'s tinyc.c language).\n# Ported from grammars-v4 tinyc/tinyc.g4 (commit 7df52be9).\n# Copyright (c) 2013, Tom Everett. BSD licence (see NOTICE.md).\n\nstart program;\nwhitespace [ \\r\\n\\t]+;\n\nprogram --> statement+ ;\n\n# ANTLR resolves the dangling \'else\' greedily (an \'else\' binds to the\n# nearest \'if\'). An Earley parser sees both readings, so statements are split\n# into matched (every \'if\' has its \'else\') and open forms.\nstatement --> matched | open ;\n\nmatched --> \'if\' paren_expr matched \'else\' matched\n         | \'while\' paren_expr matched\n         | \'do\' statement \'while\' paren_expr \';\'\n         | \'{\' statement* \'}\'\n         | expr \';\'\n         | \';\' ;\n\nopen --> \'if\' paren_expr statement | \'if\' paren_expr matched \'else\' open | \'while\' paren_expr open ;\n\nparen_expr --> \'(\' expr \')\' ;\n\nexpr --> test | id_ \'=\' expr ;\n\ntest --> sum_ | sum_ \'<\' sum_ ;\n\nsum_ --> term | sum_ \'+\' term | sum_ \'-\' term ;\n\nterm --> id_ | integer | paren_expr ;\n\nid_ --> STRING ;\n\ninteger --> INT ;\n\n# In ANTLR the implicit keyword tokens win over STRING on equal length;\n# here the keywords are excluded from STRING with a lookahead.\nSTRING --> (?!(?:if|else|while|do)(?![a-z]))[a-z]+ ;\n\nINT --> [0-9]+ ;\n',
    'inputs.txt': 'x=1;\nif (a) if (b) ; else ;\n{ while (i<j) i=i-1; }\nif = 1;\ndo ; while (x)\n',
  },
