    'grammar.ug': '# Port of grammars-v4 toml/TomlLexer.g4 and toml/TomlParser.g4 (commit 7df52be9), TOML.\n# Original grammar: Apache License, Version 2.0 (Apache Software Foundation header).\n#\n# Lexer modes are lexical states: DEFAULT is ANTLR\'s default mode, and VALUE, INLINE\n# and ARRAY are SIMPLE_VALUE_MODE, INLINE_TABLE_MODE and ARRAY_MODE. pushMode(X) is\n# \'==> X\', mode(X) is \'==> ^X\' and popMode is \'==> _\'. ANTLR\'s WS is the whitespace;\n# line breaks and comments are tokens, except inside arrays (see NOTICE.md).\n\nstart document;\nwhitespace [ \\t]+;\nskip ARRAY_NL, ARRAY_COMMENT;\n\ndocument --> expression (NL expression)* ;\n\nexpression --> key_value comment | table comment | comment ;\n\ncomment --> COMMENT? ;\n\nkey_value --> key EQUALS value ;\n\nkey --> simple_key | dotted_key ;\n\nsimple_key --> quoted_key | unquoted_key ;\n\nunquoted_key --> UNQUOTED_KEY ;\n\nquoted_key --> BASIC_STRING | LITERAL_STRING ;\n\ndotted_key --> simple_key (DOT simple_key)+ ;\n\nvalue --> string | integer | floating_point | bool_ | date_time | array_ | inline_table ;\n\nstring --> BASIC_STRING | ML_BASIC_STRING | LITERAL_STRING | ML_LITERAL_STRING ;\n\ninteger --> DEC_INT | HEX_INT | OCT_INT | BIN_INT ;\n\nfloating_point --> FLOAT | INF | NAN ;\n\nbool_ --> BOOLEAN ;\n\ndate_time --> OFFSET_DATE_TIME | LOCAL_DATE_TIME | LOCAL_DATE | LOCAL_TIME ;\n\n# ANTLR: L_BRACKET array_values? comment_or_nl R_BRACKET, where array_values wraps\n# each value in comment_or_nl and nl_or_comment. Inside arrays line breaks and\n# comments are skipped instead (ARRAY_NL, ARRAY_COMMENT), see NOTICE.md.\narray_ --> L_BRACKET array_values? R_BRACKET ;\n\narray_values --> value COMMA array_values | value COMMA? ;\n\ntable --> standard_table | array_table ;\n\nstandard_table --> L_BRACKET key R_BRACKET ;\n\ninline_table --> L_BRACE inline_table_keyvals R_BRACE ;\n\ninline_table_keyvals --> inline_table_keyvals_non_empty? ;\n\ninline_table_keyvals_non_empty --> key EQUALS value (COMMA inline_table_keyvals_non_empty)? ;\n\narray_table --> DOUBLE_L_BRACKET key DOUBLE_R_BRACKET ;\n\n# ---------------------------------------------------------------- lexer\n\n# Default mode.\nNL --> {DEFAULT} (?:[\\r]?[\\n])+ ;\nCOMMENT --> {DEFAULT} \'#\' [^\\n]* ;\nL_BRACKET --> {DEFAULT} \'[\' ;\nDOUBLE_L_BRACKET --> {DEFAULT} \'[[\' ;\nR_BRACKET --> {DEFAULT} \']\' ;\nDOUBLE_R_BRACKET --> {DEFAULT} \']]\' ;\nEQUALS --> {DEFAULT} \'=\' ==> VALUE ;\nDOT --> {DEFAULT} \'.\' ;\nCOMMA --> {DEFAULT} \',\' ;\nBASIC_STRING --> {DEFAULT} \'"\' (?:\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\\\n])* \'"\' ;\nLITERAL_STRING --> {DEFAULT} "\'" [^\'\\n]* "\'" ;\nUNQUOTED_KEY --> {DEFAULT} [A-Za-z0-9_\\-]+ ;\n\n# Inline table mode.\nDOT --> {INLINE} \'.\' ;\nCOMMA --> {INLINE} \',\' ;\nR_BRACE --> {INLINE} \'}\' ==> _ ;\nBASIC_STRING --> {INLINE} \'"\' (?:\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\\\n])* \'"\' ;\nLITERAL_STRING --> {INLINE} "\'" [^\'\\n]* "\'" ;\nUNQUOTED_KEY --> {INLINE} [A-Za-z0-9_\\-]+ ;\nEQUALS --> {INLINE} \'=\' ==> VALUE ;\n\n# Array mode: values are lexed in place, and nested arrays and inline tables push.\nARRAY_NL --> {ARRAY} (?:[\\r]?[\\n])+ ;\nARRAY_COMMENT --> {ARRAY} \'#\' [^\\n]* ;\nCOMMA --> {ARRAY} \',\' ;\nL_BRACE --> {ARRAY} \'{\' ==> INLINE ;\nL_BRACKET --> {ARRAY} \'[\' ==> ARRAY ;\nR_BRACKET --> {ARRAY} \']\' ==> _ ;\nBOOLEAN --> {ARRAY} (?:true|false) ;\nBASIC_STRING --> {ARRAY} \'"\' (?:\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\\\n])* \'"\' ;\nML_BASIC_STRING --> {ARRAY} \'"""\' (?:\\\\\\r?\\n|\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\])* \'"""\' ;\nLITERAL_STRING --> {ARRAY} "\'" [^\'\\n]* "\'" ;\nML_LITERAL_STRING --> {ARRAY} "\'\'\'" (?:[\\s\\S]*?) "\'\'\'" ;\nFLOAT --> {ARRAY} (?:[+-]?(?:[1-9](?:[0-9]|_[0-9])+|[0-9])(?:[eE][+-]?[0-9](?:[0-9]|_[0-9])*|\\.[0-9](?:[0-9]|_[0-9])*(?:[eE][+-]?[0-9](?:[0-9]|_[0-9])*)?)) ;\nINF --> {ARRAY} [+\\-]? \'inf\' ;\nNAN --> {ARRAY} [+\\-]? \'nan\' ;\nDEC_INT --> {ARRAY} (?:[+-]?(?:[1-9](?:[0-9]|_[0-9])+|[0-9])) ;\nHEX_INT --> {ARRAY} \'0x\' (?:[0-9A-Fa-f](?:[0-9A-Fa-f]|_[0-9A-Fa-f])*) ;\nOCT_INT --> {ARRAY} \'0o\' (?:[0-7](?:[0-7]|_[0-7])*) ;\nBIN_INT --> {ARRAY} \'0b\' (?:[01](?:[01]|_[01])*) ;\nOFFSET_DATE_TIME --> {ARRAY} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?(?:Z|[+-][0-9]{2}:[0-9]{2})) ;\nLOCAL_DATE_TIME --> {ARRAY} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?) ;\nLOCAL_DATE --> {ARRAY} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}) ;\nLOCAL_TIME --> {ARRAY} (?:[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?) ;\n\n# Simple value mode: one scalar, then back to the enclosing mode; an inline table or\n# an array replaces the mode.\nL_BRACE --> {VALUE} \'{\' ==> ^INLINE ;\nL_BRACKET --> {VALUE} \'[\' ==> ^ARRAY ;\nBOOLEAN --> {VALUE} (?:true|false) ==> _ ;\n\nBASIC_STRING --> {VALUE} \'"\' (?:\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\\\n])* \'"\' ==> _ ;\nML_BASIC_STRING --> {VALUE} \'"""\' (?:\\\\\\r?\\n|\\\\(?:["\\\\/bfnrt]|u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8})|[^"\\\\])* \'"""\' ==> _ ;\nLITERAL_STRING --> {VALUE} "\'" [^\'\\n]* "\'" ==> _ ;\nML_LITERAL_STRING --> {VALUE} "\'\'\'" (?:[\\s\\S]*?) "\'\'\'" ==> _ ;\n\nFLOAT --> {VALUE} (?:[+-]?(?:[1-9](?:[0-9]|_[0-9])+|[0-9])(?:[eE][+-]?[0-9](?:[0-9]|_[0-9])*|\\.[0-9](?:[0-9]|_[0-9])*(?:[eE][+-]?[0-9](?:[0-9]|_[0-9])*)?)) ==> _ ;\nINF --> {VALUE} [+\\-]? \'inf\' ==> _ ;\nNAN --> {VALUE} [+\\-]? \'nan\' ==> _ ;\n\nDEC_INT --> {VALUE} (?:[+-]?(?:[1-9](?:[0-9]|_[0-9])+|[0-9])) ==> _ ;\nHEX_INT --> {VALUE} \'0x\' (?:[0-9A-Fa-f](?:[0-9A-Fa-f]|_[0-9A-Fa-f])*) ==> _ ;\nOCT_INT --> {VALUE} \'0o\' (?:[0-7](?:[0-7]|_[0-7])*) ==> _ ;\nBIN_INT --> {VALUE} \'0b\' (?:[01](?:[01]|_[01])*) ==> _ ;\n\nOFFSET_DATE_TIME --> {VALUE} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?(?:Z|[+-][0-9]{2}:[0-9]{2})) ==> _ ;\nLOCAL_DATE_TIME --> {VALUE} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?) ==> _ ;\nLOCAL_DATE --> {VALUE} (?:[0-9]{4}-[0-9]{2}-[0-9]{2}) ==> _ ;\nLOCAL_TIME --> {VALUE} (?:[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?) ==> _ ;\n',
