    'grammar.ug': '# Turtle (Terse RDF Triple Language).\n# Ported from grammars-v4 turtle/TURTLE.g4 (commit 7df52be9).\n# Copyright (c) 2014 Alejandro Medrano (Universidad Politecnica de Madrid).\n# BSD licence (see NOTICE.md). Derived from http://www.w3.org/TR/turtle/#sec-grammar-grammar\n#\n# ANTLR helper lexer rules are inlined into the regexes of the token\n# categories the parser uses.\n\nstart turtleDoc;\nwhitespace [\\t\\r\\n\\u000C ]+;\nskip LC;\n\nturtleDoc --> statement* ;\n\nstatement --> directive | triples \'.\' ;\n\ndirective --> prefixID | base | sparqlPrefix | sparqlBase ;\n\nprefixID --> \'@prefix\' PNAME_NS IRIREF \'.\' ;\n\nbase --> \'@base\' IRIREF \'.\' ;\n\nsparqlBase --> \'BASE\' IRIREF ;\n\nsparqlPrefix --> \'PREFIX\' PNAME_NS IRIREF ;\n\ntriples --> subject predicateObjectList | blankNodePropertyList predicateObjectList? ;\n\npredicateObjectList --> verb objectList (\';\' (verb objectList)?)* ;\n\nobjectList --> object_ (\',\' object_)* ;\n\nverb --> predicate | \'a\' ;\n\nsubject --> iri | BlankNode | collection ;\n\npredicate --> iri ;\n\nobject_ --> iri | BlankNode | collection | blankNodePropertyList | literal ;\n\nliteral --> rdfLiteral | NumericLiteral | BooleanLiteral ;\n\nblankNodePropertyList --> \'[\' predicateObjectList \']\' ;\n\ncollection --> \'(\' object_* \')\' ;\n\nrdfLiteral --> String (LANGTAG | \'^^\' iri)? ;\n\niri --> IRIREF | PrefixedName ;\n\nPrefixedName --> PNAME_LN | PNAME_NS ;\n\n# INTEGER | DECIMAL | DOUBLE, longest alternatives first.\nNumericLiteral --> [+-]? (?:[0-9]+[.][0-9]*[eE][+-]?[0-9]+|[.][0-9]+[eE][+-]?[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]*[.][0-9]+|[0-9]+) ;\n\nBooleanLiteral --> (?:true|false) ;\n\n# STRING_LITERAL_LONG_SINGLE_QUOTE | STRING_LITERAL_LONG_QUOTE |\n# STRING_LITERAL_QUOTE | STRING_LITERAL_SINGLE_QUOTE (W3C definitions).\nString --> (?:\'\'\'(?:(?:\'|\'\')?(?:[^\'\\\\]|\\\\[tbnrf"\'\\\\]|\\\\u[0-9A-Fa-f]{4}|\\\\U[0-9A-Fa-f]{8}))*\'\'\'|"""(?:(?:"|"")?(?:[^"\\\\]|\\\\[tbnrf"\'\\\\]|\\\\u[0-9A-Fa-f]{4}|\\\\U[0-9A-Fa-f]{8}))*"""|"(?:[^"\\\\\\r\\n]|\\\\[tbnrf"\'\\\\]|\\\\u[0-9A-Fa-f]{4}|\\\\U[0-9A-Fa-f]{8})*"|\'(?:[^\'\\\\\\r\\n]|\\\\[tbnrf"\'\\\\]|\\\\u[0-9A-Fa-f]{4}|\\\\U[0-9A-Fa-f]{8})*\') ;\n\n# BLANK_NODE_LABEL | ANON\nBlankNode --> (?:_:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_0-9](?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀.]*[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀])?|\\[[ \\t\\r\\n]*\\]) ;\n\nIRIREF --> \'<\' (?:[^\\u0000- <>"{}|^`\\\\]|\\\\u[0-9A-Fa-f]{4}|\\\\U[0-9A-Fa-f]{8})* \'>\' ;\n\n# PN_PREFIX? \':\'\nPNAME_NS --> (?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�](?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀.]*[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀])?)? \':\' ;\n\n# PNAME_NS PN_LOCAL, where PLX is PERCENT | PN_LOCAL_ESC.\nPNAME_LN --> (?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�](?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀.]*[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀])?)? \':\' (?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_:0-9]|%[0-9A-Fa-f]{2}|\\\\[_~.\\-!\$&\'\\(\\)*+,;=/?#@%]) (?:(?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀.:]|%[0-9A-Fa-f]{2}|\\\\[_~.\\-!\$&\'\\(\\)*+,;=/?#@%])*(?:[A-Za-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�_\\-0-9·̀-ͯ‿-⁀:]|%[0-9A-Fa-f]{2}|\\\\[_~.\\-!\$&\'\\(\\)*+,;=/?#@%]))? ;\n\n# ANTLR\'s \'@prefix\' and \'@base\' literals win ties against LANGTAG.\nLANGTAG --> \'@\' (?!(?:prefix|base)(?![a-zA-Z0-9-])) [a-zA-Z]+ (?:-[a-zA-Z0-9]+)* ;\n\nLC --> \'#\' [^\\r\\n]+ ;\n',
    'inputs.txt': '@prefix : <x> .\n:a a :b, 1.5 .\n[] <p> "x"@en # c\\n.\n<a> <b> "x"@base .\n"s" <p> <o> .\n',
