  'port-url': {
    'case.json': '{\n  "rules": [\n    "S-G1",\n    "S-G3",\n    "S-L2",\n    "S-P8"\n  ],\n  "description": "Port of grammars-v4 url: \'::\' versus \':\' by maximal munch, DIGITS and HEX winning equal-length ties because STRING excludes them, and an IPv6 host."\n}\n',
