                       "text": "1",\n                                    "start": 10,\n                                    "end": 11\n                                  }\n                                ]\n                              }\n                            ]\n                          }\n                        ]\n                      },\n                      {\n                        "text": "]",\n                        "start": 11,\n                        "end": 12\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": ":",\n                "start": 12,\n                "end": 13\n              },\n              {\n                "symbol": "port",\n                "children": [\n                  {\n                    "symbol": "DIGITS",\n                    "children": [\n                      {\n                        "text": "80",\n                        "start": 13,\n                        "end": 15\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": "/",\n                "start": 15,\n                "end": 16\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "a://h?x=%20",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "url",\n        "children": [\n          {\n            "symbol": "uri",\n            "children": [\n              {\n                "symbol": "scheme",\n                "children": [\n                  {\n                    "symbol": "string",\n                    "children": [\n                      {\n                        "symbol": "STRING",\n                        "children": [\n                          {\n                            "text": "a",\n                            "start": 0,\n                            "end": 1\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": "://",\n                "start": 1,\n                "end": 4\n              },\n              {\n                "symbol": "host",\n                "children": [\n                  {\n                    "symbol": "hostname",\n                    "children": [\n                      {\n                        "symbol": "string",\n                        "children": [\n                          {\n                            "symbol": "STRING",\n                            "children": [\n                              {\n                                "text": "h",\n                                "start": 4,\n                                "end": 5\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "query",\n                "children": [\n                  {\n                    "text": "?",\n                    "start": 5,\n                    "end": 6\n                  },\n                  {\n                    "symbol": "search",\n                    "children": [\n                      {\n                        "symbol": "searchparameter",\n                        "children": [\n                          {\n                            "symbol": "string",\n                            "children": [\n                              {\n                                "symbol": "STRING",\n                                "children": [\n                                  {\n                                    "text": "x",\n                                    "start": 6,\n                                    "end": 7\n                                  }\n                                ]\n                              }\n                            ]\n                          },\n                          {\n                            "text": "=",\n                            "start": 7,\n                            "end": 8\n                          },\n                          {\n                            "symbol": "HEX",\n                            "children": [\n                              {\n                                "text": "%20",\n                                "start": 8,\n                                "end": 11\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "s://h:8080",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "url",\n        "children": [\n          {\n            "symbol": "uri",\n            "children": [\n              {\n                "symbol": "scheme",\n                "children": [\n                  {\n                    "symbol": "string",\n                    "children": [\n                      {\n                        "symbol": "STRING",\n                        "children": [\n                          {\n                            "text": "s",\n                            "start": 0,\n                            "end": 1\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": "://",\n                "start": 1,\n                "end": 4\n              },\n              {\n                "symbol": "host",\n                "children": [\n                  {\n                    "symbol": "hostname",\n                    "children": [\n                      {\n                        "symbol": "string",\n                        "children": [\n                          {\n                            "symbol": "STRING",\n                            "children": [\n                              {\n                                "text": "h",\n                                "start": 4,\n                                "end": 5\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": ":",\n                "start": 5,\n                "end": 6\n              },\n              {\n                "symbol": "port",\n                "children": [\n                  {\n                    "symbol": "DIGITS",\n                    "children": [\n                      {\n                        "text": "8080",\n                        "start": 6,\n                        "end": 10\n                      }\n                    ]\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "http://h:80a/",\n      "outcome": "rejected"\n    },\n    {\n      "input": "http//h",\n      "outcome": "rejected"\n    },\n    {\n      "input": "a://h\\n\\n",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "url",\n        "children": [\n          {\n            "symbol": "uri",\n            "children": [\n              {\n                "symbol": "scheme",\n                "children": [\n                  {\n                    "symbol": "string",\n                    "children": [\n                      {\n                        "symbol": "STRING",\n                        "children": [\n                          {\n                            "text": "a",\n                            "start": 0,\n                            "end": 1\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": "://",\n                "start": 1,\n                "end": 4\n              },\n              {\n                "symbol": "host",\n                "children": [\n                  {\n                    "symbol": "hostname",\n                    "children": [\n                      {\n                        "symbol": "string",\n                        "children": [\n                          {\n                            "symbol": "STRING",\n                            "children": [\n                              {\n                                "text": "h",\n                                "start": 4,\n                                "end": 5\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "WS",\n                "children": [\n                  {\n                    "text": "\\n\\n",\n                    "start": 5,\n                    "end": 7\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      "input": "http :// h",\n      "outcome": "rejected"\n    },\n    {\n      "input": "a://h\\r\\n",\n      "outcome": "accepted",\n      "penalty": 0,\n      "ambiguous": false,\n      "tree": {\n        "symbol": "url",\n        "children": [\n          {\n            "symbol": "uri",\n            "children": [\n              {\n                "symbol": "scheme",\n                "children": [\n                  {\n                    "symbol": "string",\n                    "children": [\n                      {\n                        "symbol": "STRING",\n                        "children": [\n                          {\n                            "text": "a",\n                            "start": 0,\n                            "end": 1\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "text": "://",\n                "start": 1,\n                "end": 4\n              },\n              {\n                "symbol": "host",\n                "children": [\n                  {\n                    "symbol": "hostname",\n                    "children": [\n                      {\n                        "symbol": "string",\n                        "children": [\n                          {\n                            "symbol": "STRING",\n                            "children": [\n                              {\n                                "text": "h",\n                                "start": 4,\n                                "end": 5\n                              }\n                            ]\n                          }\n                        ]\n                      }\n                    ]\n                  }\n                ]\n              },\n              {\n                "symbol": "WS",\n                "children": [\n                  {\n                    "text": "\\r\\n",\n                    "start": 5,\n                    "end": 7\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n',
    'grammar.ug': '# Port of grammars-v4 url/url.g4 (commit 7df52be9), URLs of the form\n#   scheme:[//[user:password@]host[:port]][/]path[?query][#fragment]\n# Original grammar: Copyright (c) 2016, Tom Everett, BSD 3-Clause License.\n# Nothing is skipped: as in ANTLR, only a trailing run of line breaks (WS) may follow a URL.\n\nstart url;\nwhitespace none;\n\nurl --> uri ;\n\nuri --> scheme \'://\' login? host (\':\' port)? (\'/\' path?)? query? frag? WS? ;\n\nscheme --> string ;\n\nhost --> \'/\'? hostname ;\n\nhostname --> string | \'[\' v6host \']\' ;\n\n# ANTLR: \'::\'? (string | DIGITS) ((\':\' | \'::\') (string | DIGITS))*\nv6host --> \'::\'? string ((\':\' | \'::\') string)* ;\n\nport --> DIGITS ;\n\npath --> string (\'/\' string)* \'/\'? ;\n\nuser --> string ;\n\nlogin --> user (\':\' password)? \'@\' ;\n\npassword --> string ;\n\n# ANTLR: \'#\' (string | DIGITS)\nfrag --> \'#\' string ;\n\nquery --> \'?\' search ;\n\nsearch --> searchparameter (\'&\' searchparameter)* ;\n\n# ANTLR: string (\'=\' (string | DIGITS | HEX))?\nsearchparameter --> string (\'=\' (string | HEX))? ;\n\nstring --> STRING | DIGITS ;\n\nDIGITS --> [0-9]+ ;\n\nHEX --> (?:%[a-fA-F0-9][a-fA-F0-9])+ ;\n\n# ANTLR resolves equal-length ties by rule order, so a run of digits is DIGITS\n# and a run of %XX escapes is HEX. STRING excludes exactly those matches.\nSTRING --> (?!(?:[0-9]+|(?:%[a-fA-F0-9][a-fA-F0-9])+)(?![a-zA-Z0-9.+\\-]|%[a-fA-F0-9][a-fA-F0-9])) (?:[a-zA-Z~0-9]|%[a-fA-F0-9][a-fA-F0-9]) (?:[a-zA-Z0-9.+\\-]|%[a-fA-F0-9][a-fA-F0-9])* ;\n\nWS --> [\\r\\n]+ ;\n',
    'inputs.txt': 'http://[::1]:80/\na://h?x=%20\ns://h:8080\nhttp://h:80a/\nhttp//h\na://h\\n\\n\nhttp :// h\na://h\\r\\n\n',
  },
  'review-constraint-split': {
