    'grammar.ug': '# SIMPLE language (converted from SIMPLE.g4) in unification grammar form\n# This is a pragmatic subset sufficient for parser tests.\n\nstart program;\n\n# Program: sequence of declarations or statements\nprogram --> item*;\nitem --> record_declaration;\nitem --> function_declaration;\nitem --> variable_declaration;\nitem --> statement;\n\n# ===== Declarations =====\n\nrecord_declaration --> KW_record Identifier LPAR record_fields? RPAR record_body?;\nrecord_fields --> record_field;\nrecord_fields --> record_fields COMMA record_field;\nrecord_field --> type Identifier;\nrecord_body --> LBRACE factory_method* RBRACE;\nfactory_method --> function_declaration;\n\nfunction_declaration --> type Identifier LPAR parameter_list? RPAR block;\n\nparameter_list --> normal_parameters;\nparameter_list --> normal_parameters COMMA optional_parameters;\nparameter_list --> optional_parameters;\n\nnormal_parameters --> parameter;\nnormal_parameters --> normal_parameters COMMA parameter;\nparameter --> type Identifier;\n\noptional_parameters --> optional_positional_parameters;\noptional_parameters --> named_parameters;\n\noptional_positional_parameters --> LBRACKET default_parameter_list RBRACKET;\ndefault_parameter_list --> default_parameter;\ndefault_parameter_list --> default_parameter_list COMMA default_parameter;\ndefault_parameter --> type Identifier;\ndefault_parameter --> type Identifier ASSIGN expression;\n\nnamed_parameters --> LBRACE named_parameter_list RBRACE;\nnamed_parameter_list --> named_parameter;\nnamed_parameter_list --> named_parameter_list COMMA named_parameter;\nnamed_parameter --> KW_required? type Identifier;\nnamed_parameter --> KW_required? type Identifier ASSIGN expression;\n\nvariable_declaration --> variable_modifier* type Identifier SEMI;\nvariable_declaration --> variable_modifier* type Identifier ASSIGN expression SEMI;\nvariable_modifier --> KW_late;\nvariable_modifier --> KW_final;\n\n# ===== Types =====\ntype --> KW_var;\ntype --> base_type (QMARK)?;\nbase_type --> KW_int;\nbase_type --> KW_double;\nbase_type --> KW_String;\nbase_type --> KW_bool;\nbase_type --> KW_void;\nbase_type --> Identifier;\n\n# ===== Statements =====\nstatement --> block;\nstatement --> if_statement;\nstatement --> while_statement;\nstatement --> for_statement;\nstatement --> return_statement;\nstatement --> expression_statement;\n\nblock --> LBRACE statement* RBRACE;\n\nif_statement --> KW_if LPAR expression RPAR statement;\nif_statement --> KW_if LPAR expression RPAR statement KW_else statement;\n\nwhile_statement --> KW_while LPAR expression RPAR statement;\n\nfor_statement --> KW_for LPAR for_init SEMI expression? SEMI expression? RPAR statement;\nfor_init --> variable_declaration;\nfor_init --> expression_statement;\nfor_init --> SEMI;\n\nreturn_statement --> KW_return expression? SEMI;\n\nexpression_statement --> expression? SEMI;\n\n# ===== Expressions =====\nexpression --> assignment_expression;\n\nassignment_expression --> Identifier assignment_operator expression;\nassignment_expression --> null_coalescing_expression;\n\nassignment_operator --> NULL_ASSIGN;\nassignment_operator --> ASSIGN;\n\nnull_coalescing_expression --> null_aware_expression;\nnull_coalescing_expression --> null_coalescing_expression NULL_COALESCE null_aware_expression;\nnull_aware_expression --> member_access;\n\nmember_access --> primary;\nmember_access --> member_access DOT Identifier;\nmember_access --> member_access SAFE_DOT Identifier;\n\nprimary --> LPAR expression RPAR;\nprimary --> literal;\nprimary --> Identifier;\nprimary --> method_call;\nprimary --> primary EXCL;\n\nmethod_call --> Identifier LPAR argument_list? RPAR;\nargument_list --> expression;\nargument_list --> argument_list COMMA expression;\n\n# ===== Literals and Identifiers =====\nliteral --> IntegerLiteral;\nliteral --> FloatingPointLiteral;\nliteral --> StringLiteral;\nliteral --> KW_true;\nliteral --> KW_false;\nliteral --> KW_null;\n\n# Lexical categories\nIdentifier --> [a-zA-Z_][a-zA-Z_0-9]*;\nIntegerLiteral --> [0-9]+;\nFloatingPointLiteral --> [0-9]+ \'.\' [0-9]+;\nStringLiteral --> \'"\' [^"\\\\]* \'"\';\n\n# Keyword and punctuation tokens (must be listed before Identifier to win)\nKW_record --> \'record\';\nKW_if --> \'if\';\nKW_else --> \'else\';\nKW_for --> \'for\';\nKW_while --> \'while\';\nKW_return --> \'return\';\nKW_required --> \'required\';\nKW_late --> \'late\';\nKW_final --> \'final\';\nKW_var --> \'variable\';\nKW_int --> \'int\';\nKW_double --> \'double\';\nKW_String --> \'String\';\nKW_bool --> \'bool\';\nKW_void --> \'void\';\nKW_true --> \'true\';\nKW_false --> \'false\';\nKW_null --> \'null\';\n\nLPAR --> \'(\';\nRPAR --> \')\';\nLBRACE --> \'{\';\nRBRACE --> \'}\';\nLBRACKET --> \'[\';\nRBRACKET --> \']\';\nCOMMA --> \',\';\nSEMI --> \';\';\nDOT --> \'.\';\nSAFE_DOT --> \'?.\';\nQMARK --> \'?\';\nASSIGN --> \'=\';\nNULL_COALESCE --> \'??\';\nNULL_ASSIGN --> \'??=\';\nEXCL --> \'!\';\n',
